import { useEffect, useState } from 'react';
import { supabase } from '@/integrations/supabase/client';

interface DatabaseData {
  categories: number;
  tasks: number;
  projects: number;
  sampleCategory: any;
  sampleTask: any;
  sampleProject: any;
}

export default function DatabaseCheck() {
  console.log('DatabaseCheck component loaded');

  return (
    <div>
      <h1>Database Check Page</h1>
      <p>Testing if the component loads</p>
    </div>
  );
}

import { useState } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";
import { useToast } from "@/hooks/use-toast";
import {
  FileText,
  FileImage,
  FileArchive,
  File as FileIcon,
  Download,
  Trash2,
  Eye,
} from "lucide-react";
import { format } from "date-fns";
import { he } from "date-fns/locale";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import { FilePreview } from "./FilePreview";

interface Attachment {
  id: string;
  file_url: string;
  file_name: string;
  file_type: string;
  file_size: number;
  uploaded_at: string;
  uploaded_by: string;
}

interface AttachmentsListProps {
  projectTaskId: string;
}

const getFileIcon = (fileType: string) => {
  if (fileType.startsWith("image/")) return FileImage;
  if (fileType.includes("pdf")) return FileText;
  if (fileType.includes("zip") || fileType.includes("compressed")) return FileArchive;
  if (fileType.includes("word") || fileType.includes("document")) return FileText;
  if (fileType.includes("excel") || fileType.includes("spreadsheet")) return FileText;
  return FileIcon;
};

export function AttachmentsList({ projectTaskId }: AttachmentsListProps) {
  const { toast } = useToast();
  const queryClient = useQueryClient();
  const [deletingId, setDeletingId] = useState<string | null>(null);
  const [previewFile, setPreviewFile] = useState<Attachment | null>(null);

  const { data: attachments, isLoading } = useQuery({
    queryKey: ["task-attachments", projectTaskId],
    queryFn: async () => {
      const { data, error } = await supabase
        .from("task_attachments")
        .select("*")
        .eq("project_task_id", projectTaskId)
        .order("uploaded_at", { ascending: false });

      if (error) throw error;
      return data as Attachment[];
    },
  });

  const deleteMutation = useMutation({
    mutationFn: async (attachmentId: string) => {
      const attachment = attachments?.find((a) => a.id === attachmentId);
      if (!attachment) throw new Error("Attachment not found");

      // Extract file path from URL
      const urlParts = attachment.file_url.split("/");
      const filePath = urlParts.slice(-2).join("/");

      // Delete from storage
      const { error: storageError } = await supabase.storage
        .from("task-files")
        .remove([filePath]);

      if (storageError) throw storageError;

      // Delete from database
      const { error: dbError } = await supabase
        .from("task_attachments")
        .delete()
        .eq("id", attachmentId);

      if (dbError) throw dbError;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["task-attachments", projectTaskId] });
      toast({ title: "הקובץ נמחק בהצלחה" });
      setDeletingId(null);
    },
    onError: (error: any) => {
      toast({
        title: "שגיאה במחיקת הקובץ",
        description: error.message,
        variant: "destructive",
      });
    },
  });

  const handleDownload = async (attachment: Attachment) => {
    try {
      const response = await fetch(attachment.file_url);
      const blob = await response.blob();
      const url = window.URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = attachment.file_name;
      document.body.appendChild(a);
      a.click();
      window.URL.revokeObjectURL(url);
      document.body.removeChild(a);
    } catch (error: any) {
      toast({
        title: "שגיאה בהורדת הקובץ",
        description: error.message,
        variant: "destructive",
      });
    }
  };

  if (isLoading) {
    return (
      <div className="space-y-2">
        {[1, 2].map((i) => (
          <Card key={i} className="p-4 animate-pulse">
            <div className="h-4 bg-muted rounded w-3/4"></div>
          </Card>
        ))}
      </div>
    );
  }

  if (!attachments || attachments.length === 0) {
    return (
      <div className="text-center py-8 text-muted-foreground">
        <FileIcon className="h-12 w-12 mx-auto mb-2 opacity-50" />
        <p>אין קבצים מצורפים</p>
      </div>
    );
  }

  return (
    <>
      <div className="space-y-2">
        {attachments.map((attachment) => {
          const Icon = getFileIcon(attachment.file_type);
          const canPreview = attachment.file_type.startsWith("image/") || 
                            attachment.file_type.includes("pdf");

          return (
            <Card key={attachment.id} className="p-4">
              <div className="flex items-center justify-between gap-4">
                <div className="flex items-center gap-3 flex-1 min-w-0">
                  <Icon className="h-5 w-5 text-muted-foreground shrink-0" />
                  <div className="flex-1 min-w-0">
                    <p className="font-medium truncate">{attachment.file_name}</p>
                    <p className="text-xs text-muted-foreground">
                      {(attachment.file_size / 1024).toFixed(1)} KB •{" "}
                      {format(new Date(attachment.uploaded_at), "d/M/yy HH:mm", {
                        locale: he,
                      })}
                    </p>
                  </div>
                </div>

                <div className="flex gap-1 shrink-0">
                  {canPreview && (
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={() => setPreviewFile(attachment)}
                      title="תצוגה מקדימה"
                    >
                      <Eye className="h-4 w-4" />
                    </Button>
                  )}
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={() => handleDownload(attachment)}
                    title="הורדה"
                  >
                    <Download className="h-4 w-4" />
                  </Button>
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={() => setDeletingId(attachment.id)}
                    title="מחיקה"
                  >
                    <Trash2 className="h-4 w-4 text-destructive" />
                  </Button>
                </div>
              </div>
            </Card>
          );
        })}
      </div>

      <AlertDialog open={!!deletingId} onOpenChange={() => setDeletingId(null)}>
        <AlertDialogContent dir="rtl">
          <AlertDialogHeader>
            <AlertDialogTitle>האם למחוק את הקובץ?</AlertDialogTitle>
            <AlertDialogDescription>
              פעולה זו תמחק את הקובץ לצמיתות ולא ניתן לבטל אותה.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>ביטול</AlertDialogCancel>
            <AlertDialogAction
              onClick={() => deletingId && deleteMutation.mutate(deletingId)}
            >
              מחק
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      {previewFile && (
        <FilePreview
          fileUrl={previewFile.file_url}
          fileName={previewFile.file_name}
          fileType={previewFile.file_type}
          isOpen={!!previewFile}
          onClose={() => setPreviewFile(null)}
        />
      )}
    </>
  );
}

import { useState } from 'react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { Download, Upload, AlertCircle, Clock, Trash2, Search, Tag } from 'lucide-react';
import { useToast } from '@/hooks/use-toast';
import { supabase } from '@/integrations/supabase/client';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { Alert, AlertDescription } from '@/components/ui/alert';
import { useAuth } from '@/hooks/useAuth';
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from '@/components/ui/alert-dialog';

interface BackupRestoreProps {
  projectId: string;
}

interface Backup {
  id: string;
  backup_name: string;
  created_at: string;
  backup_size: number;
  backup_type: 'manual' | 'auto' | 'scheduled';
  notes?: string;
  tasks_count: number;
  completed_count: number;
}

export const BackupRestore = ({ projectId }: BackupRestoreProps) => {
  const { toast } = useToast();
  const queryClient = useQueryClient();
  const { user } = useAuth();
  const [isCreatingBackup, setIsCreatingBackup] = useState(false);
  const [isRestoring, setIsRestoring] = useState(false);
  const [backupName, setBackupName] = useState('');
  const [backupNotes, setBackupNotes] = useState('');
  const [searchQuery, setSearchQuery] = useState('');
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
  const [selectedBackupId, setSelectedBackupId] = useState<string | null>(null);

  const { data: backups = [], isLoading } = useQuery({
    queryKey: ['project-backups', projectId],
    queryFn: async () => {
      const { data, error } = await supabase
        .from('project_backups')
        .select('*')
        .eq('project_id', projectId)
        .order('created_at', { ascending: false });

      if (error) throw error;

      return (data || []).map(backup => {
        const backupData = backup.backup_data as any;
        return {
          id: backup.id,
          backup_name: backup.backup_name,
          created_at: backup.created_at,
          backup_size: backup.backup_size,
          backup_type: backup.backup_type as 'manual' | 'auto' | 'scheduled',
          notes: backup.notes,
          tasks_count: backupData?.tasks?.length || 0,
          completed_count: backupData?.tasks?.filter((t: any) => t.completed).length || 0,
        };
      });
    },
  });

  const handleCreateBackup = async () => {
    if (!user) return;

    setIsCreatingBackup(true);
    try {
      // Fetch all project data
      const { data: project } = await supabase
        .from('projects')
        .select('*')
        .eq('id', projectId)
        .single();

      const { data: projectTasks } = await supabase
        .from('project_tasks')
        .select('*, tasks(*)')
        .eq('project_id', projectId);

      const { data: attachments } = await supabase
        .from('task_attachments')
        .select('*')
        .in('project_task_id', projectTasks?.map(pt => pt.id) || []);

      const { data: reminders } = await supabase
        .from('task_reminders')
        .select('*')
        .in('project_task_id', projectTasks?.map(pt => pt.id) || []);

      const backupData = {
        project,
        tasks: projectTasks,
        attachments,
        reminders,
        created_at: new Date().toISOString(),
      };

      const backupJson = JSON.stringify(backupData);
      const backupSize = new Blob([backupJson]).size;

      const name = backupName.trim() || `גיבוי ${new Date().toLocaleDateString('he-IL')} ${new Date().toLocaleTimeString('he-IL', { hour: '2-digit', minute: '2-digit' })}`;

      const { error } = await supabase
        .from('project_backups')
        .insert({
          project_id: projectId,
          backup_name: name,
          backup_data: backupData,
          files_metadata: { attachments_count: attachments?.length || 0 },
          created_by: user.id,
          backup_size: backupSize,
          backup_type: 'manual',
          notes: backupNotes.trim() || null,
        });

      if (error) throw error;

      await queryClient.invalidateQueries({ queryKey: ['project-backups'] });

      setBackupName('');
      setBackupNotes('');

      toast({
        title: 'גיבוי נוצר בהצלחה',
        description: `${projectTasks?.length || 0} משימות, ${attachments?.length || 0} קבצים, ${reminders?.length || 0} תזכורות נשמרו`,
      });
    } catch (error) {
      console.error('Backup error:', error);
      toast({
        title: 'שגיאה',
        description: 'לא ניתן ליצור גיבוי',
        variant: 'destructive',
      });
    } finally {
      setIsCreatingBackup(false);
    }
  };

  const handleRestore = async (backupId: string) => {
    if (!user) return;

    setIsRestoring(true);
    try {
      const { data: backup } = await supabase
        .from('project_backups')
        .select('*')
        .eq('id', backupId)
        .single();

      if (!backup) throw new Error('גיבוי לא נמצא');

      const backupData = backup.backup_data as any;

      // Delete current data
      const { data: currentTasks } = await supabase
        .from('project_tasks')
        .select('id')
        .eq('project_id', projectId);

      if (currentTasks && currentTasks.length > 0) {
        await supabase
          .from('project_tasks')
          .delete()
          .in('id', currentTasks.map(t => t.id));
      }

      // Restore tasks
      if (backupData.tasks && backupData.tasks.length > 0) {
        const { error: tasksError } = await supabase
          .from('project_tasks')
          .insert(backupData.tasks.map((task: any) => ({
            id: task.id,
            project_id: projectId,
            task_id: task.task_id,
            completed: task.completed,
            status: task.status,
            notes: task.notes,
            started_at: task.started_at,
            completed_at: task.completed_at,
            due_date_override: task.due_date_override,
            actual_hours: task.actual_hours,
          })));

        if (tasksError) throw tasksError;
      }

      // Restore reminders
      if (backupData.reminders && backupData.reminders.length > 0) {
        await supabase
          .from('task_reminders')
          .insert(backupData.reminders);
      }

      await queryClient.invalidateQueries({ queryKey: ['project-tasks'] });
      await queryClient.invalidateQueries({ queryKey: ['task-reminders'] });

      toast({
        title: 'שוחזר בהצלחה',
        description: `${backupData.tasks?.length || 0} משימות ו-${backupData.reminders?.length || 0} תזכורות שוחזרו`,
      });
    } catch (error) {
      console.error('Restore error:', error);
      toast({
        title: 'שגיאה',
        description: 'לא ניתן לשחזר גיבוי',
        variant: 'destructive',
      });
    } finally {
      setIsRestoring(false);
    }
  };

  const deleteMutation = useMutation({
    mutationFn: async (backupId: string) => {
      const { error } = await supabase
        .from('project_backups')
        .delete()
        .eq('id', backupId);

      if (error) throw error;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['project-backups'] });
      toast({
        title: 'גיבוי נמחק',
        description: 'הגיבוי נמחק בהצלחה',
      });
      setDeleteDialogOpen(false);
      setSelectedBackupId(null);
    },
    onError: (error) => {
      console.error('Delete error:', error);
      toast({
        title: 'שגיאה',
        description: 'לא ניתן למחוק את הגיבוי',
        variant: 'destructive',
      });
    },
  });

  const filteredBackups = backups.filter(backup =>
    backup.backup_name.toLowerCase().includes(searchQuery.toLowerCase()) ||
    backup.notes?.toLowerCase().includes(searchQuery.toLowerCase())
  );

  const formatFileSize = (bytes: number) => {
    if (bytes < 1024) return bytes + ' B';
    if (bytes < 1024 * 1024) return (bytes / 1024).toFixed(2) + ' KB';
    return (bytes / (1024 * 1024)).toFixed(2) + ' MB';
  };

  if (isLoading) {
    return <div>טוען...</div>;
  }

  return (
    <div className="space-y-6">
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Download className="h-5 w-5" />
            יצירת גיבוי חדש
          </CardTitle>
          <CardDescription>
            שמור את כל נתוני הפרויקט במסד הנתונים לשחזור עתידי
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div>
            <label className="text-sm font-medium mb-2 block">שם הגיבוי (אופציונלי)</label>
            <Input
              placeholder="לדוגמה: לפני שינויים גדולים"
              value={backupName}
              onChange={(e) => setBackupName(e.target.value)}
            />
          </div>
          <div>
            <label className="text-sm font-medium mb-2 block">הערות (אופציונלי)</label>
            <Textarea
              placeholder="הערות על הגיבוי..."
              value={backupNotes}
              onChange={(e) => setBackupNotes(e.target.value)}
              rows={3}
            />
          </div>
          <Button
            onClick={handleCreateBackup}
            disabled={isCreatingBackup}
            className="w-full"
          >
            <Download className="ml-2 h-4 w-4" />
            {isCreatingBackup ? 'יוצר גיבוי...' : 'צור גיבוי חדש'}
          </Button>
        </CardContent>
      </Card>

      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Upload className="h-5 w-5" />
            גיבויים קיימים
          </CardTitle>
          <CardDescription>
            שחזר את הפרויקט לנקודת זמן קודמת
          </CardDescription>
        </CardHeader>
        <CardContent>
          {backups.length > 0 && (
            <div className="mb-4">
              <div className="relative">
                <Search className="absolute right-3 top-3 h-4 w-4 text-muted-foreground" />
                <Input
                  placeholder="חיפוש גיבויים..."
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  className="pr-10"
                />
              </div>
            </div>
          )}

          {filteredBackups.length === 0 ? (
            <p className="text-center text-muted-foreground py-8">
              {backups.length === 0 ? 'אין גיבויים זמינים' : 'לא נמצאו גיבויים מתאימים'}
            </p>
          ) : (
            <div className="space-y-3">
              {filteredBackups.map((backup) => (
                <div
                  key={backup.id}
                  className="flex items-start justify-between p-4 border rounded-lg hover:bg-accent/50 transition-colors"
                >
                  <div className="flex items-start gap-3 flex-1">
                    <div className="mt-1">
                      {backup.backup_type === 'auto' && <Clock className="h-4 w-4 text-muted-foreground" />}
                      {backup.backup_type === 'manual' && <Download className="h-4 w-4 text-muted-foreground" />}
                      {backup.backup_type === 'scheduled' && <Tag className="h-4 w-4 text-muted-foreground" />}
                    </div>
                    <div className="flex-1">
                      <p className="font-medium">{backup.backup_name}</p>
                      <p className="text-sm text-muted-foreground">
                        {new Date(backup.created_at).toLocaleDateString('he-IL')} • {new Date(backup.created_at).toLocaleTimeString('he-IL')}
                      </p>
                      <p className="text-xs text-muted-foreground mt-1">
                        {backup.tasks_count} משימות • {backup.completed_count} הושלמו • {formatFileSize(backup.backup_size)}
                      </p>
                      {backup.notes && (
                        <p className="text-xs text-muted-foreground mt-2 italic">
                          {backup.notes}
                        </p>
                      )}
                    </div>
                  </div>
                  <div className="flex gap-2">
                    <Button
                      onClick={() => handleRestore(backup.id)}
                      disabled={isRestoring}
                      variant="outline"
                      size="sm"
                    >
                      <Upload className="ml-2 h-4 w-4" />
                      שחזר
                    </Button>
                    <Button
                      onClick={() => {
                        setSelectedBackupId(backup.id);
                        setDeleteDialogOpen(true);
                      }}
                      variant="ghost"
                      size="sm"
                    >
                      <Trash2 className="h-4 w-4" />
                    </Button>
                  </div>
                </div>
              ))}
            </div>
          )}
        </CardContent>
      </Card>

      <Card className="border-yellow-500/50 bg-yellow-500/5">
        <CardHeader>
          <CardTitle className="flex items-center gap-2 text-yellow-700 dark:text-yellow-500">
            <AlertCircle className="h-5 w-5" />
            הערה חשובה
          </CardTitle>
        </CardHeader>
        <CardContent className="text-sm text-muted-foreground space-y-2">
          <p>• הגיבויים נשמרים במסד הנתונים</p>
          <p>• גיבוי אוטומטי נוצר לפני כל שחזור</p>
          <p>• שחזור גיבוי ידרוס את כל המשימות והתזכורות הנוכחיות</p>
          <p>• מומלץ ליצור גיבוי לפני שינויים משמעותיים</p>
        </CardContent>
      </Card>

      <AlertDialog open={deleteDialogOpen} onOpenChange={setDeleteDialogOpen}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>האם למחוק גיבוי זה?</AlertDialogTitle>
            <AlertDialogDescription>
              פעולה זו אינה הפיכה. הגיבוי יימחק לצמיתות.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>ביטול</AlertDialogCancel>
            <AlertDialogAction
              onClick={() => selectedBackupId && deleteMutation.mutate(selectedBackupId)}
              className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
            >
              מחק
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
};

import { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import {
  CommandDialog,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from '@/components/ui/command';
import { Search, Folder, CheckSquare, Calendar, Settings, BarChart3, Map } from 'lucide-react';

interface CommandPaletteProps {
  projectId?: string;
  onNavigate?: (view: string) => void;
}

export const CommandPalette = ({ projectId, onNavigate }: CommandPaletteProps) => {
  const [open, setOpen] = useState(false);
  const navigate = useNavigate();

  useEffect(() => {
    const down = (e: KeyboardEvent) => {
      if (e.key === 'k' && (e.metaKey || e.ctrlKey)) {
        e.preventDefault();
        setOpen((open) => !open);
      }
    };

    document.addEventListener('keydown', down);
    return () => document.removeEventListener('keydown', down);
  }, []);

  const handleSelect = (action: string) => {
    setOpen(false);

    if (action.startsWith('view:') && onNavigate) {
      onNavigate(action.replace('view:', ''));
    } else if (action === 'home') {
      navigate('/');
    } else if (action === 'new-project') {
      navigate('/project/new');
    }
  };

  return (
    <CommandDialog open={open} onOpenChange={setOpen}>
        <CommandInput placeholder="חפש פעולות, דפים, משימות..." />
        <CommandList>
          <CommandEmpty>לא נמצאו תוצאות</CommandEmpty>

          <CommandGroup heading="ניווט">
            <CommandItem onSelect={() => handleSelect('home')}>
              <Folder className="ml-2 h-4 w-4" />
