  tasks: Task[];
  onStatusChange: (taskId: string, newStatus: string) => void | Promise<void>;
  onTaskClick: (task: Task) => void;
  projectId?: string;
  allTasks?: Task[];
  categories?: Category[];
}

interface KanbanStatus {
  id: string;
  name: string;
  label: string;
  color: string;
  order_index: number;
  icon: string;
  project_id?: string;
}

const iconMap: Record<
  string,
  React.ComponentType<{ className?: string; style?: React.CSSProperties }>
> = {
  circle: Circle,
  clock: Clock,
  "alert-circle": AlertCircle,
  "check-circle-2": CheckCircle2,
};

const priorityColors = {
  low: "bg-muted text-muted-foreground",
  medium: "bg-info text-white",
  high: "bg-warning text-white",
  urgent: "bg-destructive text-white",
};

const getPriorityLabel = (
  priority?: "low" | "medium" | "high" | "urgent",
): string => {
  if (priority === "urgent") return "דחוף";
  if (priority === "high") return "גבוה";
  if (priority === "medium") return "בינוני";
  return "נמוך";
};

export const KanbanBoard = ({
  tasks,
  onStatusChange,
  onTaskClick,
  projectId,
  allTasks = [],
  categories = [],
}: KanbanBoardProps) => {
  const { toast } = useToast();
  const queryClient = useQueryClient();
  const { isAdmin } = useIsAdmin();
  const [draggedTask, setDraggedTask] = useState<Task | null>(null);
  const [dragOverStatus, setDragOverStatus] = useState<string | null>(null);
  const [selectedTasks, setSelectedTasks] = useState<Set<string>>(new Set());
  const [isMultiSelectMode, setIsMultiSelectMode] = useState(false);
  const [manageDialogOpen, setManageDialogOpen] = useState(false);
  const [newStatusLabel, setNewStatusLabel] = useState("");
  const [newStatusColor, setNewStatusColor] = useState("#6B7280");
  const [taskDialogOpen, setTaskDialogOpen] = useState(false);
  const [categoryDialogOpen, setCategoryDialogOpen] = useState(false);
  const [selectedCategoryId, setSelectedCategoryId] = useState("");
  const [reminderDialogOpen, setReminderDialogOpen] = useState(false);
  const [selectedProjectTaskId, setSelectedProjectTaskId] = useState<
    string | null
  >(null);

  const { data: statuses = [] } = useQuery({
    queryKey: ["kanban-statuses", projectId],
    queryFn: async () => {
      const { data, error } = await supabase
        .from("kanban_statuses")
        .select("*")
        .or(
          projectId
            ? `project_id.is.null,project_id.eq.${projectId}`
            : "project_id.is.null",
        )
        .order("order_index", { ascending: true });

      if (error) throw error;
      return data as KanbanStatus[];
    },
  });

  const createStatusMutation = useMutation({
    mutationFn: async (newStatus: { label: string; color: string }) => {
      const maxOrder = Math.max(...statuses.map((s) => s.order_index), 0);
      const { error } = await supabase.from("kanban_statuses").insert({
        name: newStatus.label.toLowerCase().replace(/\s+/g, "_"),
        label: newStatus.label,
        color: newStatus.color,
        order_index: maxOrder + 1,
        icon: "circle",
        project_id: projectId || null,
      });

      if (error) throw error;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({
        queryKey: ["kanban-statuses", projectId],
      });
      setNewStatusLabel("");
      setNewStatusColor("#6B7280");
      toast({
        title: "נוסף בהצלחה",
        description: "הסטטוס החדש נוסף ללוח",
      });
    },
    onError: (error) => {
      toast({
        title: "שגיאה",
        description: "לא ניתן להוסיף סטטוס",
        variant: "destructive",
      });
      console.error("Error creating status:", error);
    },
  });

  const deleteStatusMutation = useMutation({
    mutationFn: async (statusId: string) => {
      const { error } = await supabase
        .from("kanban_statuses")
        .delete()
        .eq("id", statusId);

      if (error) throw error;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({
        queryKey: ["kanban-statuses", projectId],
      });
      toast({
        title: "נמחק בהצלחה",
        description: "הסטטוס הוסר מהלוח",
      });
    },
    onError: (error) => {
      toast({
        title: "שגיאה",
        description: "לא ניתן למחוק סטטוס",
        variant: "destructive",
      });
      console.error("Error deleting status:", error);
    },
  });

  const handleDragStart = (task: Task, e: React.DragEvent) => {
    setDraggedTask(task);
    e.dataTransfer.effectAllowed = "move";
    e.dataTransfer.setData("text/plain", task.id);
    // Add visual feedback
    if (e.currentTarget instanceof HTMLElement) {
      e.currentTarget.style.opacity = "0.5";
    }
  };

  const handleDragEnd = (e: React.DragEvent) => {
    if (e.currentTarget instanceof HTMLElement) {
      e.currentTarget.style.opacity = "1";
    }
    setDraggedTask(null);
    setDragOverStatus(null);
  };

  const handleDragOver = (e: React.DragEvent, status: string) => {
    e.preventDefault();
    e.dataTransfer.dropEffect = "move";
    setDragOverStatus(status);
  };

  const handleDragLeave = (e: React.DragEvent) => {
    // Only clear if leaving the drop zone entirely
    if (e.currentTarget === e.target) {
      setDragOverStatus(null);
    }
  };

  const handleDrop = async (status: string, e: React.DragEvent) => {
    e.preventDefault();
    setDragOverStatus(null);

    if (draggedTask && draggedTask.status !== status) {
      try {
        await onStatusChange(draggedTask.id, status);
        toast({
          title: "המשימה עודכנה",
          description: `המשימה הועברה ל${statuses.find((s) => s.name === status)?.label || status}`,
        });
      } catch {
        toast({
          title: "שגיאה",
          description: "לא ניתן להעביר את המשימה",
          variant: "destructive",
        });
      }
    }
    setDraggedTask(null);
  };

  const getTasksByStatus = (status: string) => {
    return tasks.filter((task) => task.status === status);
  };

  const toggleTaskSelection = (taskId: string) => {
    const newSelected = new Set(selectedTasks);
    if (newSelected.has(taskId)) {
      newSelected.delete(taskId);
    } else {
      newSelected.add(taskId);
    }
    setSelectedTasks(newSelected);
  };

  const selectAllInStatus = (status: string) => {
    const statusTasks = getTasksByStatus(status);
    const newSelected = new Set(selectedTasks);
    for (const task of statusTasks) {
      newSelected.add(task.id);
    }
    setSelectedTasks(newSelected);
  };

  const clearSelection = () => {
    setSelectedTasks(new Set());
    setIsMultiSelectMode(false);
  };

  const deleteSelectedTasks = async () => {
    if (selectedTasks.size === 0) return;

    if (!confirm(`האם אתה בטוח שברצונך למחוק ${selectedTasks.size} משימות?`)) {
      return;
    }

    try {
      // Delete all selected tasks
      const deletePromises = Array.from(selectedTasks).map((taskId) =>
        supabase.from("project_tasks").delete().eq("id", taskId),
      );

      await Promise.all(deletePromises);

      queryClient.invalidateQueries({ queryKey: ["project-tasks"] });

      toast({
        title: "נמחקו בהצלחה",
        description: `${selectedTasks.size} משימות נמחקו`,
      });

      clearSelection();
    } catch {
      toast({
        title: "שגיאה במחיקה",
        description: "לא ניתן למחוק את המשימות",
        variant: "destructive",
      });
    }
  };

  const moveSelectedTasks = async (newStatus: string) => {
    if (selectedTasks.size === 0) return;

    try {
      const movePromises: Promise<void>[] = Array.from(selectedTasks).map(
        (taskId) => Promise.resolve(onStatusChange(taskId, newStatus)),
      );

      await Promise.all(movePromises);

      toast({
        title: "הועברו בהצלחה",
        description: `${selectedTasks.size} משימות הועברו`,
      });

      clearSelection();
    } catch {
      toast({
        title: "שגיאה בהעברה",
        description: "לא ניתן להעביר את המשימות",
        variant: "destructive",
      });
    }
  };

  // Handler for reminder button click
  const handleReminderClick = (e: React.MouseEvent, taskId: string) => {
    e.stopPropagation();
    const projectTask = tasks.find((t) => t.id === taskId);
    if (projectTask) {
      setSelectedProjectTaskId(projectTask.id);
      setReminderDialogOpen(true);
    }
  };

  // Handler for status change in dropdown
  const handleTaskStatusChange = (
    e: React.MouseEvent,
    taskId: string,
    newStatus: string,
  ) => {
    e.stopPropagation();
    onStatusChange(taskId, newStatus);
  };

  const handleAddStatus = () => {
    if (!newStatusLabel.trim()) {
      toast({
        title: "שגיאה",
        description: "יש להזין שם לסטטוס",
        variant: "destructive",
      });
      return;
    }

    createStatusMutation.mutate({
      label: newStatusLabel,
      color: newStatusColor,
    });
  };

  return (
    <div className="space-y-4">
      <div className="flex justify-between items-center gap-2">
        <div className="flex gap-2">
          {isMultiSelectMode && (
            <>
              <Button onClick={clearSelection} variant="outline" size="sm">
                ביטול בחירה ({selectedTasks.size})
              </Button>
              {selectedTasks.size > 0 && (
                <>
                  <DropdownMenu>
                    <DropdownMenuTrigger asChild>
                      <Button variant="outline" size="sm">
                        העבר ל...
                      </Button>
                    </DropdownMenuTrigger>
                    <DropdownMenuContent>
                      {statuses.map((status) => (
                        <DropdownMenuItem
                          key={status.id}
                          onClick={() => moveSelectedTasks(status.name)}
                        >
                          {status.label}
                        </DropdownMenuItem>
                      ))}
                    </DropdownMenuContent>
                  </DropdownMenu>
                  <Button
                    onClick={deleteSelectedTasks}
                    variant="destructive"
                    size="sm"
                  >
                    <Trash2 className="h-4 w-4 ml-1" />
                    מחק ({selectedTasks.size})
                  </Button>
                </>
              )}
            </>
          )}
          {!isMultiSelectMode && (
            <Button
              onClick={() => setIsMultiSelectMode(true)}
              variant="outline"
              size="sm"
            >
              בחירה מרובה
            </Button>
          )}
        </div>

        <div className="flex gap-2">
          <Button
            onClick={() => setCategoryDialogOpen(true)}
            variant="outline"
            size="sm"
          >
            <Plus className="h-4 w-4 ml-1" />
            הוסף קטגוריה
          </Button>
          {isAdmin && (
            <Dialog open={manageDialogOpen} onOpenChange={setManageDialogOpen}>
              <DialogTrigger asChild>
                <Button variant="outline" size="sm">
                  <Settings className="h-4 w-4 ml-1" />
                  ניהול סטטוסים
                </Button>
              </DialogTrigger>
              <DialogContent className="max-w-2xl" dir="rtl">
                <DialogHeader>
                  <DialogTitle>ניהול סטטוסים בלוח קנבן</DialogTitle>
                  <DialogDescription>
                    הוסף, ערוך או מחק סטטוסים בלוח הקנבן
                  </DialogDescription>
                </DialogHeader>

                <div className="space-y-6 pt-4">
                  <div className="space-y-4">
                    <h3 className="text-sm font-semibold">הוספת סטטוס חדש</h3>
                    <div className="flex gap-3">
                      <div className="flex-1">
                        <Label htmlFor="status-label">שם הסטטוס</Label>
                        <Input
                          id="status-label"
                          value={newStatusLabel}
                          onChange={(e) => setNewStatusLabel(e.target.value)}
                          placeholder="לדוגמה: בבדיקת איכות"
                        />
                      </div>
                      <div className="w-32">
                        <Label htmlFor="status-color">צבע</Label>
                        <div className="flex gap-2">
                          <Input
                            id="status-color"
                            type="color"
                            value={newStatusColor}
                            onChange={(e) => setNewStatusColor(e.target.value)}
                            className="h-10 w-16 p-1"
                          />
                          {/* eslint-disable-next-line react/style-prop-object, react/no-unknown-property, react/no-danger */}
                          <div
                            className="h-10 w-10 rounded border"
                            style={{ backgroundColor: newStatusColor }}
                          />
                        </div>
                      </div>
                      <div className="flex items-end">
                        <Button
                          onClick={handleAddStatus}
                          disabled={createStatusMutation.isPending}
                        >
                          <Plus className="h-4 w-4 ml-1" />
                          הוסף
                        </Button>
                      </div>
                    </div>
                  </div>

                  <div className="space-y-3">
                    <h3 className="text-sm font-semibold">סטטוסים קיימים</h3>
                    <div className="space-y-2 max-h-[300px] overflow-y-auto">
                      {statuses.map((status) => (
                        <div
                          key={status.id}
                          className="flex items-center justify-between p-3 rounded-lg border bg-card hover:bg-accent/50 transition-colors"
                        >
                          <div className="flex items-center gap-3">
                            {/* eslint-disable-next-line react/style-prop-object, react/no-unknown-property, react/no-danger */}
                            <div
                              className="w-4 h-4 rounded-full"
                              style={{ backgroundColor: status.color }}
                            />
                            <span className="font-medium">{status.label}</span>
                            {status.project_id && (
                              <Badge variant="secondary" className="text-xs">
                                מותאם אישית
                              </Badge>
                            )}
                          </div>
                          {status.project_id && (
                            <Button
                              variant="ghost"
                              size="sm"
                              onClick={() =>
                                deleteStatusMutation.mutate(status.id)
                              }
                              disabled={deleteStatusMutation.isPending}
                            >
                              <Trash2 className="h-4 w-4 text-destructive" />
                            </Button>
                          )}
                        </div>
                      ))}
                    </div>
                  </div>
                </div>
              </DialogContent>
            </Dialog>
          )}
        </div>
      </div>

      <div
        className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4 pb-6"
        style={{
          gridTemplateColumns: `repeat(${statuses.length}, minmax(0, 1fr))`,
        }}
      >
        {statuses.map((statusConfig) => {
          const statusTasks = getTasksByStatus(statusConfig.name);
          const StatusIcon = iconMap[statusConfig.icon] || Circle;

          return (
            <section
              key={statusConfig.id}
              aria-label={`עמודת ${statusConfig.label}`}
              className={cn(
                "flex flex-col gap-3 min-w-[250px] p-2 rounded-lg transition-all",
                dragOverStatus === statusConfig.name &&
                  "bg-primary/10 ring-2 ring-primary",
              )}
              onDragOver={(e) => handleDragOver(e, statusConfig.name)}
              onDragLeave={handleDragLeave}
              onDrop={(e) => handleDrop(statusConfig.name, e)}
            >
              <Card className="border-2 animate-fade-in">
                <CardHeader className="pb-3">
                  <CardTitle className="flex items-center justify-between text-base">
                    <div className="flex items-center gap-2">
                      {/* eslint-disable-next-line react/style-prop-object, react/no-unknown-property, react/no-danger */}
                      <StatusIcon
                        className="h-4 w-4"
                        style={{ color: statusConfig.color }}
                      />
                      <span>{statusConfig.label}</span>
                    </div>
                    <div className="flex items-center gap-2">
                      {isMultiSelectMode && statusTasks.length > 0 && (
                        <Button
                          variant="ghost"
                          size="sm"
                          className="h-6 text-xs"
                          onClick={() => selectAllInStatus(statusConfig.name)}
                        >
                          בחר הכל
                        </Button>
                      )}
                      <Badge variant="secondary" className="rounded-full">
                        {statusTasks.length}
                      </Badge>
                    </div>
                  </CardTitle>
                </CardHeader>
              </Card>

              <div className="flex flex-col gap-2 min-h-[200px]">
                {statusTasks.map((task) => (
                  <Card
                    key={task.id}
                    draggable
                    onDragStart={(e) => handleDragStart(task, e)}
                    onDragEnd={handleDragEnd}
                    className={cn(
                      "cursor-move hover:scale-[1.02] transition-transform",
                      draggedTask?.id === task.id && "opacity-50",
                      selectedTasks.has(task.id) && "ring-2 ring-primary",
                      isMultiSelectMode && "cursor-pointer",
                    )}
                    style={{
                      backgroundColor: `${statusConfig.color}15`,
                      borderLeft: `3px solid ${statusConfig.color}`,
                    }}
                    onClick={(e) => {
                      if (isMultiSelectMode) {
                        e.stopPropagation();
                        toggleTaskSelection(task.id);
                      } else {
                        onTaskClick(task);
                      }
                    }}
                  >
                    <CardContent className="p-4">
                      <div className="flex items-start justify-between gap-2 mb-2">
                        <h4 className="font-medium text-sm line-clamp-2">
                          {task.name}
                        </h4>
                        <div className="flex gap-1">
                          <Button
                            variant="ghost"
                            size="icon"
                            className="h-6 w-6"
                            onClick={(e) => handleReminderClick(e, task.id)}
                          >
                            <Bell className="h-3 w-3" />
                          </Button>
                          <DropdownMenu>
                            <DropdownMenuTrigger
                              asChild
                              onClick={(e) => e.stopPropagation()}
                            >
                              <Button
                                variant="ghost"
                                size="icon"
                                className="h-6 w-6"
                              >
                                <MoreVertical className="h-4 w-4" />
                              </Button>
                            </DropdownMenuTrigger>
                            <DropdownMenuContent
                              align="end"
                              className="bg-popover z-50"
                            >
                              {statuses.map(
                                (newStatus) =>
                                  newStatus.name !== statusConfig.name && (
                                    <DropdownMenuItem
                                      key={newStatus.id}
                                      onClick={(e) =>
                                        handleTaskStatusChange(
                                          e,
                                          task.id,
                                          newStatus.name,
                                        )
                                      }
                                    >
                                      העבר ל{newStatus.label}
                                    </DropdownMenuItem>
                                  ),
                              )}
                            </DropdownMenuContent>
                          </DropdownMenu>
                        </div>
                      </div>

                      <div className="flex items-center gap-2 flex-wrap">
                        {task.priority && (
                          <Badge
                            className={cn(
                              "text-xs",
                              priorityColors[task.priority],
                            )}
                          >
                            {getPriorityLabel(task.priority)}
                          </Badge>
                        )}
                        {task.dueDate && (
                          <span className="text-xs text-muted-foreground">
                            {new Date(task.dueDate).toLocaleDateString("he-IL")}
                          </span>
                        )}
                      </div>
                    </CardContent>
                  </Card>
                ))}

                {statusTasks.length === 0 && (
                  <div className="flex items-center justify-center h-32 border-2 border-dashed rounded-lg text-muted-foreground text-sm">
                    גרור משימות לכאן
                  </div>
                )}
              </div>
            </section>
          );
        })}
      </div>

      {/* Dialogs */}
      {isAdmin && selectedCategoryId && allTasks && (
        <TaskManagementDialog
          isOpen={taskDialogOpen}
          onClose={() => {
            setTaskDialogOpen(false);
            setSelectedCategoryId("");
          }}
          categoryId={selectedCategoryId}
          categoryName={
            categories.find((c) => c.id === selectedCategoryId)?.display_name ||
            ""
          }
          // eslint-disable-next-line @typescript-eslint/no-explicit-any
          tasks={allTasks as any}
        />
      )}

      {isAdmin && categories && (
        <CategoryManagementDialog
          isOpen={categoryDialogOpen}
          onClose={() => setCategoryDialogOpen(false)}
          // eslint-disable-next-line @typescript-eslint/no-explicit-any
          categories={categories as any}
        />
      )}

      {selectedProjectTaskId && (
        <ReminderManager
          projectTaskId={selectedProjectTaskId}
          taskName={
            tasks.find((t) => t.id === selectedProjectTaskId)?.name || ""
          }
          isOpen={reminderDialogOpen}
          onClose={() => {
            setReminderDialogOpen(false);
            setSelectedProjectTaskId(null);
          }}
        />
      )}
    </div>
  );
};

import { useQuery } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Progress } from "@/components/ui/progress";
import { Badge } from "@/components/ui/badge";
import { Avatar, AvatarFallback } from "@/components/ui/avatar";
import { CheckCircle, Clock, AlertCircle, TrendingUp, Calendar, Users, Target, Zap } from "lucide-react";
import { format } from "date-fns";
import { he } from "date-fns/locale";
interface ProjectDashboardProps {
  projectId: string;
}
export function ProjectDashboard({
  projectId
}: ProjectDashboardProps) {
  const {
    data: projectTasks
  } = useQuery({
    queryKey: ["project-dashboard", projectId],
    queryFn: async () => {
      const {
        data,
        error
      } = await supabase.from("project_tasks").select(`
          *,
          tasks (
            name,
            priority,
            estimated_hours,
            categories (display_name)
          ),
          profiles:assigned_to (
            full_name,
            email
          )
        `).eq("project_id", projectId);
      if (error) throw error;
      return data;
    }
  });

  // Calculate KPIs
  const totalTasks = projectTasks?.length || 0;
  const completedTasks = projectTasks?.filter((t: any) => t.completed).length || 0;
  const inProgressTasks = projectTasks?.filter((t: any) => !t.completed && t.progress > 0).length || 0;
  const overdueTasks = projectTasks?.filter((t: any) => !t.completed && t.due_date_override && new Date(t.due_date_override) < new Date()).length || 0;
  const completionRate = totalTasks > 0 ? completedTasks / totalTasks * 100 : 0;
  const totalEstimated = projectTasks?.reduce((sum, t: any) => sum + (t.tasks?.estimated_hours || 0), 0) || 0;
  const totalActual = projectTasks?.reduce((sum, t: any) => sum + (t.actual_hours || 0), 0) || 0;

  // Get upcoming tasks (next 5)
  const upcomingTasks = projectTasks?.filter((t: any) => !t.completed && t.due_date_override).sort((a: any, b: any) => new Date(a.due_date_override).getTime() - new Date(b.due_date_override).getTime()).slice(0, 5);

  // Get team workload
  const teamWorkload = projectTasks?.reduce((acc: any[], task: any) => {
    if (task.assigned_to && task.profiles) {
      const existing = acc.find(item => item.userId === task.assigned_to);
      if (existing) {
        existing.totalTasks++;
        if (task.completed) existing.completedTasks++;
      } else {
        acc.push({
          userId: task.assigned_to,
          name: task.profiles.full_name || task.profiles.email,
          totalTasks: 1,
          completedTasks: task.completed ? 1 : 0
        });
      }
    }
    return acc;
  }, []);
  return <div className="space-y-6 animate-fade-in">
      {/* KPI Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        <Card className="border-l-4 border-l-primary overflow-hidden hover:shadow-xl transition-all duration-300">
          <CardHeader className="flex flex-row items-center justify-between pb-2 relative z-10">
            <CardTitle className="text-sm font-medium">סה"כ משימות</CardTitle>
            <div className="h-10 w-10 rounded-full bg-primary/10 flex items-center justify-center">
              <Target className="h-5 w-5 text-primary" />
            </div>
          </CardHeader>
          <CardContent className="relative z-10">
            <div className="text-3xl font-bold bg-gradient-primary bg-clip-text text-transparent">
              {totalTasks}
            </div>
            <Progress value={completionRate} className="mt-3 h-2" />
            <p className="text-xs text-muted-foreground mt-2">
              {completedTasks} הושלמו • {completionRate.toFixed(1)}%
            </p>
          </CardContent>
        </Card>

        <Card className="border-l-4 border-l-info overflow-hidden hover:shadow-xl transition-all duration-300">

          <CardHeader className="flex flex-row items-center justify-between pb-2 relative z-10">
            <CardTitle className="text-sm font-medium">בתהליך</CardTitle>
            <div className="h-10 w-10 rounded-full bg-info/10 flex items-center justify-center">
              <Zap className="h-5 w-5 text-info" />
            </div>
          </CardHeader>
          <CardContent className="relative z-10">
            <div className="text-3xl font-bold text-info">{inProgressTasks}</div>
            <p className="text-xs text-muted-foreground mt-3">
              משימות פעילות כרגע
            </p>
          </CardContent>
        </Card>

        <Card className="border-l-4 border-l-warning overflow-hidden hover:shadow-xl transition-all duration-300">

          <CardHeader className="flex flex-row items-center justify-between pb-2 relative z-10">
            <CardTitle className="text-sm font-medium">באיחור</CardTitle>
            <div className="h-10 w-10 rounded-full bg-warning/10 flex items-center justify-center animate-pulse">
              <AlertCircle className="h-5 w-5 text-warning" />
            </div>
          </CardHeader>
          <CardContent className="relative z-10">
            <div className="text-3xl font-bold text-warning">{overdueTasks}</div>
            <p className="text-xs text-muted-foreground mt-3">
              דורש טיפול מיידי 🔔
            </p>
          </CardContent>
        </Card>

        <Card className="border-l-4 border-l-success overflow-hidden hover:shadow-xl transition-all duration-300">

          <CardHeader className="flex flex-row items-center justify-between pb-2 relative z-10">
            <CardTitle className="text-sm font-medium">זמן פרויקט</CardTitle>
            <div className="h-10 w-10 rounded-full bg-success/10 flex items-center justify-center">
              <TrendingUp className="h-5 w-5 text-success" />
            </div>
          </CardHeader>
          <CardContent className="relative z-10">
            <div className="text-2xl font-bold text-success">
              {totalActual}h / {totalEstimated}h
            </div>
            <Progress value={totalEstimated > 0 ? totalActual / totalEstimated * 100 : 0} className="mt-3 h-2" />
            <p className="text-xs text-muted-foreground mt-2">
              {totalEstimated > 0 ? `${(totalActual / totalEstimated * 100).toFixed(1)}% מהזמן הושקע` : "אין הערכת זמן"}
            </p>
          </CardContent>
        </Card>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Upcoming Tasks */}
        <Card className="animate-scale-in hover:shadow-xl transition-shadow">
          <CardHeader className="bg-gradient-subtle">
            <CardTitle className="flex items-center gap-2">
              <Calendar className="h-5 w-5 text-primary" />
              משימות קרובות
            </CardTitle>
          </CardHeader>
          <CardContent className="pt-6">
            <div className="space-y-3">
              {upcomingTasks && upcomingTasks.length > 0 ? upcomingTasks.map((task: any, index: number) => {
              const isOverdue = new Date(task.due_date_override) < new Date();
              return <div key={task.id} className="flex items-center justify-between p-4 border rounded-xl hover:shadow-md hover:scale-[1.02] transition-all duration-300 bg-gradient-to-l from-transparent to-primary/5" style={{
                animationDelay: `${index * 0.1}s`
              }}>
                      <div className="flex-1">
                        <p className="font-semibold text-sm mb-2">{task.tasks?.name}</p>
                        <div className="flex items-center gap-2 flex-wrap">
                          <Badge variant={isOverdue ? "destructive" : "secondary"} className="text-xs animate-fade-in">
                            {isOverdue && "⚠️ "}
                            {format(new Date(task.due_date_override), "dd/MM/yyyy", {
                        locale: he
                      })}
                          </Badge>
                          {task.profiles && <Badge variant="outline" className="text-xs">
                              👤 {task.profiles.full_name || task.profiles.email}
                            </Badge>}
                        </div>
                      </div>
                      <div className="text-center mr-4">
                        <div className="text-2xl font-bold text-primary">{task.progress}%</div>
                        <Progress value={task.progress} className="w-16 h-2 mt-1" />
                      </div>
                    </div>;
            }) : <div className="text-center py-8">
                  <CheckCircle className="h-12 w-12 text-success mx-auto mb-3 opacity-50" />
                  <p className="text-sm text-muted-foreground">
                    אין משימות קרובות
                  </p>
                </div>}
            </div>
          </CardContent>
        </Card>

        {/* Team Workload */}
        <Card className="animate-scale-in hover:shadow-xl transition-shadow">
          <CardHeader className="bg-gradient-subtle">
            <CardTitle className="flex items-center gap-2">
              <Users className="h-5 w-5 text-primary" />
              עומס צוות
            </CardTitle>
          </CardHeader>
          <CardContent className="pt-6">
            <div className="space-y-3">
              {teamWorkload && teamWorkload.length > 0 ? teamWorkload.map((member: any, index: number) => {
              const completionRate = member.completedTasks / member.totalTasks * 100;
              return <div key={member.userId} className="flex items-center gap-3 p-4 border rounded-xl hover:shadow-md hover:scale-[1.02] transition-all duration-300 bg-gradient-to-l from-transparent to-accent/5" style={{
                animationDelay: `${index * 0.1}s`
              }}>
                      <Avatar className="h-12 w-12 ring-2 ring-primary/20">
                        <AvatarFallback className="bg-gradient-primary text-white font-bold">
                          {member.name?.[0]}
                        </AvatarFallback>
                      </Avatar>
                      <div className="flex-1">
                        <p className="font-semibold text-sm mb-2">{member.name}</p>
                        <div className="flex items-center gap-2">
                          <Progress value={completionRate} className="flex-1 h-2" />
                          <Badge variant="secondary" className="text-xs">
                            {member.completedTasks}/{member.totalTasks}
                          </Badge>
                        </div>
                      </div>
                      <div className="text-center">
                        <div className={`text-2xl font-bold ${completionRate === 100 ? 'text-success' : 'text-primary'}`}>
                          {completionRate.toFixed(0)}%
                        </div>
                      </div>
                    </div>;
            }) : <div className="text-center py-8">
                  <Users className="h-12 w-12 text-muted-foreground mx-auto mb-3 opacity-50" />
                  <p className="text-sm text-muted-foreground">
                    אין משימות משויכות לצוות
                  </p>
                </div>}
            </div>
          </CardContent>
        </Card>
      </div>
    </div>;
}

import { useState } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { supabase } from '@/integrations/supabase/client';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '@/components/ui/table';
import { Checkbox } from '@/components/ui/checkbox';
import { Badge } from '@/components/ui/badge';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { useToast } from '@/hooks/use-toast';
import { Download, Upload, RefreshCw, FileSpreadsheet, Share2, Edit2, Save, X, FileUp, Plus, GripVertical, Eye, Check, XIcon, ArrowUp, ArrowDown, ArrowUpDown, ListOrdered } from 'lucide-react';
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle, DialogTrigger } from '@/components/ui/dialog';
import { Label } from '@/components/ui/label';
import { PriorityBadge } from './PriorityBadge';
import { useDropzone } from 'react-dropzone';
import Papa from 'papaparse';
import * as XLSX from 'xlsx';
import { cn } from '@/lib/utils';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';

interface SpreadsheetViewProps {
  projectId: string;
}

interface EditingCell {
  taskId: string;
  field: 'name' | 'description' | 'status' | 'priority' | 'notes';
  value: string;
}

type ViewMode = 'compact' | 'comfortable' | 'spacious';

export const SpreadsheetView = ({ projectId }: SpreadsheetViewProps) => {
  const { toast } = useToast();
  const queryClient = useQueryClient();
  const [editingCell, setEditingCell] = useState<EditingCell | null>(null);
  const [googleSheetsUrl, setGoogleSheetsUrl] = useState('');
  const [webhookUrl, setWebhookUrl] = useState('');
  const [isExporting, setIsExporting] = useState(false);
  const [importDialogOpen, setImportDialogOpen] = useState(false);
  const [importedData, setImportedData] = useState<any[]>([]);
  const [viewMode, setViewMode] = useState<ViewMode>('comfortable');
  const [draggedRow, setDraggedRow] = useState<any | null>(null);
  const [customColumns, setCustomColumns] = useState<string[]>([]);
  const [sortConfig, setSortConfig] = useState<{ field: string; direction: 'asc' | 'desc' } | null>(null);
  const [multiSortConfig, setMultiSortConfig] = useState<Array<{
    field: string;
    direction: 'asc' | 'desc';
    priority: number;
  }>>([]);
  const [sortDialogOpen, setSortDialogOpen] = useState(false);

  const { data: tasks } = useQuery({
    queryKey: ['tasks'],
    queryFn: async () => {
      const { data, error } = await supabase
        .from('tasks')
        .select('*')
        .order('category_id', { ascending: true })
        .order('order_index', { ascending: true });
      if (error) throw error;
      return data;
    },
  });

  const { data: projectTasks } = useQuery({
    queryKey: ['project-tasks', projectId],
    queryFn: async () => {
      const { data, error } = await supabase
        .from('project_tasks')
        .select('*')
        .eq('project_id', projectId);
      if (error) throw error;
      return data;
    },
  });

  const { data: categories } = useQuery({
    queryKey: ['categories'],
    queryFn: async () => {
      const { data, error } = await supabase
        .from('categories')
        .select('*')
        .order('order_index', { ascending: true });
      if (error) throw error;
      return data;
    },
  });

  const updateTaskMutation = useMutation({
    mutationFn: async ({ taskId, field, value }: { taskId: string; field: string; value: string | number | boolean | null }) => {
      const { error } = await supabase
        .from('tasks')
        .update({ [field]: value })
        .eq('id', taskId);
      if (error) throw error;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['tasks'] });
      setEditingCell(null);
      toast({
        title: 'עודכן בהצלחה',
        description: 'השינויים נשמרו',
      });
    },
    onError: () => {
      toast({
        title: 'שגיאה',
        description: 'לא ניתן לעדכן',
        variant: 'destructive',
      });
    },
  });

  const updateProjectTaskMutation = useMutation({
    mutationFn: async ({ taskId, field, value }: { taskId: string; field: string; value: string | number | boolean | null }) => {
      const projectTask = projectTasks?.find(pt => pt.task_id === taskId);
      if (projectTask) {
        const { error } = await supabase
          .from('project_tasks')
          .update({ [field]: value })
          .eq('id', projectTask.id);
        if (error) throw error;
      }
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['project-tasks', projectId] });
      setEditingCell(null);
      toast({
        title: 'עודכן בהצלחה',
        description: 'השינויים נשמרו',
      });
    },
  });

  const toggleCompletedMutation = useMutation({
    mutationFn: async ({ taskId, completed }: { taskId: string; completed: boolean }) => {
      const projectTask = projectTasks?.find(pt => pt.task_id === taskId);
      if (projectTask) {
        const { error } = await supabase
          .from('project_tasks')
          .update({ 
            completed,
            completed_at: completed ? new Date().toISOString() : null,
            status: completed ? 'completed' : 'pending'
          })
          .eq('id', projectTask.id);
        if (error) throw error;
      }
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['project-tasks', projectId] });
    },
  });

  const exportToCSV = () => {
    if (!tasks || !categories) return;

    const headers = ['קטגוריה', 'משימה', 'תיאור', 'סטטוס', 'עדיפות', 'חובה', 'הושלם', 'הערות'];
    const rows = tasks.map(task => {
      const category = categories.find(c => c.id === task.category_id);
      const projectTask = projectTasks?.find(pt => pt.task_id === task.id);
      return [
        category?.display_name || '',
        task.name,
        task.description || '',
        projectTask?.status || 'pending',
        task.priority || 'medium',
        task.is_required ? 'כן' : 'לא',
        projectTask?.completed ? 'כן' : 'לא',
        projectTask?.notes || '',
      ];
    });

    const csv = [headers, ...rows].map(row => row.map(cell => `"${cell}"`).join(',')).join('\n');
    const blob = new Blob(['\ufeff' + csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `project_tasks_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();

    toast({
      title: 'יצוא הושלם',
      description: 'הקובץ הורד בהצלחה',
    });
  };

  const exportToGoogleSheets = async () => {
    if (!webhookUrl) {
      toast({
        title: 'שגיאה',
        description: 'אנא הזן את ה-Webhook URL של Zapier',
        variant: 'destructive',
      });
      return;
    }

    setIsExporting(true);

    try {
      const exportData = tasks?.map(task => {
        const category = categories?.find(c => c.id === task.category_id);
        const projectTask = projectTasks?.find(pt => pt.task_id === task.id);
        return {
          category: category?.display_name || '',
          task: task.name,
          description: task.description || '',
          status: projectTask?.status || 'pending',
          priority: task.priority || 'medium',
          required: task.is_required,
          completed: projectTask?.completed || false,
          notes: projectTask?.notes || '',
        };
      });

      await fetch(webhookUrl, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        mode: 'no-cors',
        body: JSON.stringify({
          tasks: exportData,
          timestamp: new Date().toISOString(),
          projectId,
        }),
      });

      toast({
        title: 'נשלח בהצלחה',
        description: 'הנתונים נשלחו ל-Google Sheets דרך Zapier',
      });
    } catch (error) {
      console.error('Error exporting to Google Sheets:', error);
      toast({
        title: 'שגיאה',
        description: 'לא ניתן לייצא ל-Google Sheets',
        variant: 'destructive',
      });
    } finally {
      setIsExporting(false);
    }
  };

  const handleCellEdit = (taskId: string, field: 'name' | 'description' | 'status' | 'priority' | 'notes', currentValue: string) => {
    setEditingCell({ taskId, field, value: currentValue || '' });
  };

  const handleSaveEdit = () => {
    if (!editingCell) return;

    if (editingCell.field === 'notes' || editingCell.field === 'status') {
      updateProjectTaskMutation.mutate({
        taskId: editingCell.taskId,
        field: editingCell.field,
        value: editingCell.value,
      });
    } else {
      updateTaskMutation.mutate({
        taskId: editingCell.taskId,
        field: editingCell.field,
        value: editingCell.value,
      });
    }
  };

  const handleCancelEdit = () => {
    setEditingCell(null);
  };

  const viewModeStyles = {
    compact: {
      padding: 'p-2',
      fontSize: 'text-xs',
      height: 'h-8',
    },
    comfortable: {
      padding: 'p-4',
      fontSize: 'text-sm',
      height: 'h-12',
    },
    spacious: {
      padding: 'p-6',
      fontSize: 'text-base',
      height: 'h-16',
    },
  };

  const handleDragStart = (task: any) => {
    setDraggedRow(task);
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
  };

  const handleDrop = (targetTask: any) => {
    if (!draggedRow || draggedRow.id === targetTask.id) return;

    toast({
      title: 'סדר מחדש',
      description: 'הסדר עודכן בהצלחה',
    });
    setDraggedRow(null);
  };

  const addNewRow = () => {
    toast({
      title: 'בקרוב',
      description: 'הוספת שורה חדשה בפיתוח',
    });
  };

  const addCustomColumn = () => {
    const columnName = prompt('שם העמודה החדשה:');
    if (columnName) {
      setCustomColumns([...customColumns, columnName]);
      toast({
        title: 'עמודה נוספה',
        description: `העמודה "${columnName}" נוספה בהצלחה`,
      });
    }
  };

  const getCellValue = (task: any, field: string) => {
    const projectTask = projectTasks?.find(pt => pt.task_id === task.id);

    if (field === 'status') return projectTask?.status || 'pending';
    if (field === 'notes') return projectTask?.notes || '';
    if (field === 'completed') return projectTask?.completed || false;

    return task[field];
  };

  const getFieldValue = (task: any, field: string): any => {
    const category = categories?.find(c => c.id === task.category_id);
    const projectTask = projectTasks?.find(pt => pt.task_id === task.id);

    switch (field) {
      case 'category':
        return category?.display_name || '';
      case 'name':
        return task.name || '';
      case 'description':
        return task.description || '';
      case 'status':
        return projectTask?.status || 'pending';
      case 'priority':
        return task.priority || 'medium';
      case 'is_required':
        return task.is_required;
      case 'completed':
        return projectTask?.completed || false;
      case 'due_date':
        return task.due_date || '';
      case 'estimated_hours':
        return task.estimated_hours || 0;
      case 'notes':
        return projectTask?.notes || '';
      default:
        return '';
    }
  };

  const compareValues = (a: any, b: any, field: string, direction: 'asc' | 'desc'): number => {
    let aVal = getFieldValue(a, field);
    let bVal = getFieldValue(b, field);

    // Special handling for priority
    if (field === 'priority') {
      const priorityOrder: Record<string, number> = { urgent: 4, high: 3, medium: 2, low: 1 };
      aVal = priorityOrder[aVal] || 0;
      bVal = priorityOrder[bVal] || 0;
    }

    // Special handling for status
    if (field === 'status') {
      const statusOrder: Record<string, number> = { pending: 1, in_progress: 2, completed: 3, blocked: 4 };
      aVal = statusOrder[aVal] || 0;
      bVal = statusOrder[bVal] || 0;
    }

    // Handle null/undefined
    if (aVal === null || aVal === undefined) aVal = '';
    if (bVal === null || bVal === undefined) bVal = '';

    // Compare
    if (aVal < bVal) return direction === 'asc' ? -1 : 1;
    if (aVal > bVal) return direction === 'asc' ? 1 : -1;
    return 0;
  };

  const applySorting = (tasksList: any[]): any[] => {
    if (!tasksList) return [];

    // If no sorting is configured, return original order (by category and order_index)
    if (multiSortConfig.length === 0 && !sortConfig) {
      return tasksList;
    }

    return [...tasksList].sort((a, b) => {
      // Apply multi-level sort if configured
      if (multiSortConfig.length > 0) {
        const sortedConfigs = [...multiSortConfig].sort((x, y) => x.priority - y.priority);
        for (const config of sortedConfigs) {
          const result = compareValues(a, b, config.field, config.direction);
          if (result !== 0) return result;
        }
        return 0;
      }

      // Apply simple sort
      if (sortConfig) {
        return compareValues(a, b, sortConfig.field, sortConfig.direction);
      }

      return 0;
    });
  };

  const handleColumnSort = (field: string) => {
    // Clear multi-sort when using simple sort
    setMultiSortConfig([]);

    if (sortConfig?.field === field) {
      setSortConfig({
        field,
        direction: sortConfig.direction === 'asc' ? 'desc' : 'asc'
      });
    } else {
      setSortConfig({ field, direction: 'asc' });
    }
  };

  const handleResetSort = () => {
    setSortConfig(null);
    setMultiSortConfig([]);
    toast({
      title: 'המיון אופס',
      description: 'חזרה לסדר ברירת המחדל',
    });
  };

  const addSortLevel = () => {
    if (multiSortConfig.length >= 5) {
      toast({
        title: 'הגבלה',
        description: 'ניתן להוסיף עד 5 רמות מיון',
        variant: 'destructive',
      });
      return;
    }

    setMultiSortConfig([
      ...multiSortConfig,
      { field: 'category', direction: 'asc', priority: multiSortConfig.length }
    ]);
  };

  const updateSortLevel = (index: number, field: string, direction: 'asc' | 'desc') => {
    const updated = [...multiSortConfig];
    updated[index] = { ...updated[index], field, direction };
    setMultiSortConfig(updated);
  };

  const removeSortLevel = (index: number) => {
    const updated = multiSortConfig.filter((_, i) => i !== index);
    // Update priorities
    const reindexed = updated.map((config, i) => ({ ...config, priority: i }));
    setMultiSortConfig(reindexed);
  };

  const applyMultiSort = () => {
    setSortConfig(null); // Clear simple sort
    setSortDialogOpen(false);
    toast({
      title: 'מיון מתקדם הוחל',
      description: `${multiSortConfig.length} רמות מיון פעילות`,
    });
  };

  const getSortedTasks = () => {
    return applySorting(tasks || []);
  };

  const handleFileUpload = (acceptedFiles: File[]) => {
    const file = acceptedFiles[0];
    if (!file) return;

    const fileExtension = file.name.split('.').pop()?.toLowerCase();

    if (fileExtension === 'csv') {
      Papa.parse(file, {
        header: true,
        complete: (results) => {
          console.log('CSV parsed:', results.data);
          setImportedData(results.data);
          toast({
            title: 'קובץ נטען בהצלחה',
            description: `נטענו ${results.data.length} שורות`,
          });
        },
        error: (error) => {
          console.error('CSV parse error:', error);
          toast({
            title: 'שגיאה',
            description: 'לא ניתן לקרוא את קובץ ה-CSV',
            variant: 'destructive',
          });
        },
      });
    } else if (fileExtension === 'xlsx' || fileExtension === 'xls') {
      const reader = new FileReader();
      reader.onload = (e) => {
        try {
          const data = new Uint8Array(e.target?.result as ArrayBuffer);
          const workbook = XLSX.read(data, { type: 'array' });
          const firstSheet = workbook.Sheets[workbook.SheetNames[0]];
          const jsonData = XLSX.utils.sheet_to_json(firstSheet);
          console.log('Excel parsed:', jsonData);
          setImportedData(jsonData);
          toast({
            title: 'קובץ נטען בהצלחה',
            description: `נטענו ${jsonData.length} שורות`,
          });
        } catch (error) {
          console.error('Excel parse error:', error);
          toast({
            title: 'שגיאה',
            description: 'לא ניתן לקרוא את קובץ ה-Excel',
            variant: 'destructive',
          });
        }
      };
      reader.readAsArrayBuffer(file);
    } else if (fileExtension === 'xml') {
      const reader = new FileReader();
      reader.onload = (e) => {
        try {
          const xmlText = e.target?.result as string;
          const parser = new DOMParser();
          const xmlDoc = parser.parseFromString(xmlText, 'text/xml');

          // Convert XML to JSON-like structure
          const rows = xmlDoc.querySelectorAll('row');
          const jsonData = Array.from(rows).map(row => {
            const obj: any = {};
            row.childNodes.forEach(node => {
              if (node.nodeType === 1) { // Element node
                obj[node.nodeName] = node.textContent;
              }
            });
            return obj;
          });

          console.log('XML parsed:', jsonData);
          setImportedData(jsonData);
          toast({
            title: 'קובץ נטען בהצלחה',
            description: `נטענו ${jsonData.length} שורות`,
          });
        } catch (error) {
          console.error('XML parse error:', error);
          toast({
            title: 'שגיאה',
            description: 'לא ניתן לקרוא את קובץ ה-XML',
            variant: 'destructive',
          });
        }
      };
      reader.readAsText(file);
    } else if (fileExtension === 'txt') {
      const reader = new FileReader();
      reader.onload = (e) => {
        try {
          const text = e.target?.result as string;
          // Try to parse as tab-separated or comma-separated
          const lines = text.split('\n').filter(line => line.trim());
          const headers = lines[0].split(/[\t,]/);
          const jsonData = lines.slice(1).map(line => {
            const values = line.split(/[\t,]/);
            const obj: any = {};
            headers.forEach((header, index) => {
              obj[header.trim()] = values[index]?.trim() || '';
            });
            return obj;
          });

          console.log('TXT parsed:', jsonData);
          setImportedData(jsonData);
          toast({
            title: 'קובץ נטען בהצלחה',
            description: `נטענו ${jsonData.length} שורות`,
          });
        } catch (error) {
          console.error('TXT parse error:', error);
          toast({
            title: 'שגיאה',
            description: 'לא ניתן לקרוא את קובץ הטקסט',
            variant: 'destructive',
          });
        }
      };
      reader.readAsText(file);
    }
  };

  const { getRootProps, getInputProps, isDragActive } = useDropzone({
