                      </TableCell>
                      <TableCell className={viewModeStyles[viewMode].padding}>
                        {isEditing && editingCell.field === 'notes' ? (
                          <div className="flex items-center gap-1">
                            <Textarea
                              value={editingCell.value}
                              onChange={(e) =>
                                setEditingCell({ ...editingCell, value: e.target.value })
                              }
                              autoFocus
                              className={cn("h-16", viewModeStyles[viewMode].fontSize)}
                            />
                            <div className="flex flex-col gap-1">
                              <Button size="icon" variant="ghost" onClick={handleSaveEdit} className="h-8 w-8">
                                <Save className="h-3 w-3" />
                              </Button>
                              <Button size="icon" variant="ghost" onClick={handleCancelEdit} className="h-8 w-8">
                                <X className="h-3 w-3" />
                              </Button>
                            </div>
                          </div>
                        ) : (
                          <div
                            className={cn("cursor-pointer group", viewModeStyles[viewMode].fontSize)}
                            onClick={() => handleCellEdit(task.id, 'notes', getCellValue(task, 'notes'))}
                          >
                            <span className="text-muted-foreground">
                              {getCellValue(task, 'notes') || 'לחץ להוספת הערה'}
                            </span>
                            <Edit2 className="h-3 w-3 inline-block mr-1 opacity-0 group-hover:opacity-100 transition-opacity" />
                          </div>
                        )}
                      </TableCell>
                      {customColumns.map((col) => (
                        <TableCell key={col} className={cn(viewModeStyles[viewMode].padding, "text-muted-foreground text-sm")}>
                          -
                        </TableCell>
                      ))}
                    </TableRow>
                  );
                })}
              </TableBody>
            </Table>
          </div>
        </CardContent>
      </Card>
    </div>
  );
};

import { useState } from "react";
import { useQuery } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { User } from "lucide-react";

interface TaskAssignmentPickerProps {
  currentAssignedTo?: string;
  onUpdate: (userId: string | null) => void;
}

export function TaskAssignmentPicker({
  currentAssignedTo,
  onUpdate,
}: TaskAssignmentPickerProps) {
  const [selectedUser, setSelectedUser] = useState<string | undefined>(
    currentAssignedTo
  );

  const { data: profiles, isLoading } = useQuery({
    queryKey: ["profiles"],
    queryFn: async () => {
      const { data, error } = await supabase
        .from("profiles")
        .select("id, full_name, email")
        .order("full_name");

      if (error) throw error;
      return data;
    },
  });

  const handleValueChange = (value: string) => {
    const userId = value === "unassigned" ? null : value;
    setSelectedUser(value === "unassigned" ? undefined : value);
    onUpdate(userId);
  };

  const selectedProfile = profiles?.find((p) => p.id === selectedUser);

  return (
    <div className="space-y-3">
      <Label>משויך ל</Label>
      <Select
        value={selectedUser || "unassigned"}
        onValueChange={handleValueChange}
        disabled={isLoading}
      >
        <SelectTrigger className="w-full">
          <SelectValue>
            {selectedProfile ? (
              <div className="flex items-center gap-2">
                <Avatar className="h-6 w-6">
                  <AvatarFallback>
                    {selectedProfile.full_name?.[0] || selectedProfile.email?.[0]}
                  </AvatarFallback>
                </Avatar>
                <span>{selectedProfile.full_name || selectedProfile.email}</span>
              </div>
            ) : (
              <div className="flex items-center gap-2">
                <User className="h-4 w-4" />
                <span>לא משויך</span>
              </div>
            )}
          </SelectValue>
        </SelectTrigger>
        <SelectContent>
          <SelectItem value="unassigned">
            <div className="flex items-center gap-2">
              <User className="h-4 w-4" />
              <span>לא משויך</span>
            </div>
          </SelectItem>
          {profiles?.map((profile) => (
            <SelectItem key={profile.id} value={profile.id}>
              <div className="flex items-center gap-2">
                <Avatar className="h-6 w-6">
                  <AvatarFallback>
                    {profile.full_name?.[0] || profile.email?.[0]}
                  </AvatarFallback>
                </Avatar>
                <span>{profile.full_name || profile.email}</span>
              </div>
            </SelectItem>
          ))}
        </SelectContent>
      </Select>
    </div>
  );
}

import { useState } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { Label } from "@/components/ui/label";
import { Button } from "@/components/ui/button";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Badge } from "@/components/ui/badge";
import { X, GitBranch } from "lucide-react";
import { toast } from "sonner";

interface TaskDependencyManagerProps {
  projectId: string;
  taskId: string;
  currentTaskName: string;
}

interface Dependency {
  id: string;
  depends_on_task_id: string;
  dependency_type: string;
  task_name: string;
}

export function TaskDependencyManager({
  projectId,
  taskId,
  currentTaskName,
}: TaskDependencyManagerProps) {
  const [selectedTaskId, setSelectedTaskId] = useState<string>("");
  const [dependencyType, setDependencyType] = useState<string>("finish_to_start");
  const queryClient = useQueryClient();

  // Fetch available tasks
  const { data: availableTasks } = useQuery({
    queryKey: ["available-tasks", projectId, taskId],
    queryFn: async () => {
      const { data, error } = await supabase
        .from("tasks")
        .select("id, name")
        .eq("category_id", (
          await supabase
            .from("project_tasks")
            .select("task_id, tasks(category_id)")
            .eq("task_id", taskId)
            .single()
        ).data?.tasks?.category_id || "")
        .neq("id", taskId)
        .order("order_index");

      if (error) throw error;
      return data;
    },
  });

  // Fetch current dependencies
  const { data: dependencies } = useQuery({
    queryKey: ["task-dependencies", taskId],
    queryFn: async () => {
      const { data, error } = await supabase
        .from("task_dependencies")
        .select(`
          id,
          depends_on_task_id,
          dependency_type,
          tasks:depends_on_task_id (
            name
          )
        `)
        .eq("task_id", taskId);

      if (error) throw error;
      return data.map((dep: any) => ({
        id: dep.id,
        depends_on_task_id: dep.depends_on_task_id,
        dependency_type: dep.dependency_type,
        task_name: dep.tasks.name,
      })) as Dependency[];
    },
  });

  // Add dependency mutation
  const addDependency = useMutation({
    mutationFn: async () => {
      const { error } = await supabase.from("task_dependencies").insert({
        project_id: projectId,
        task_id: taskId,
        depends_on_task_id: selectedTaskId,
        dependency_type: dependencyType,
      });

      if (error) throw error;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["task-dependencies"] });
      setSelectedTaskId("");
      toast.success("התלות נוספה בהצלחה");
    },
    onError: () => {
      toast.error("שגיאה בהוספת תלות");
    },
  });

  // Remove dependency mutation
  const removeDependency = useMutation({
    mutationFn: async (dependencyId: string) => {
      const { error } = await supabase
        .from("task_dependencies")
        .delete()
        .eq("id", dependencyId);

      if (error) throw error;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["task-dependencies"] });
      toast.success("התלות הוסרה בהצלחה");
    },
    onError: () => {
      toast.error("שגיאה בהסרת תלות");
    },
  });

  const getDependencyTypeLabel = (type: string) => {
    switch (type) {
      case "finish_to_start":
        return "סיום → התחלה";
      case "start_to_start":
        return "התחלה → התחלה";
      case "finish_to_finish":
        return "סיום → סיום";
      default:
        return type;
    }
  };

  return (
    <div className="space-y-4">
      <div className="flex items-center gap-2">
        <GitBranch className="h-4 w-4" />
        <Label>תלויות משימה</Label>
      </div>

      {/* Current dependencies */}
      {dependencies && dependencies.length > 0 && (
        <div className="space-y-2">
          <p className="text-sm text-muted-foreground">
            המשימה "{currentTaskName}" תלויה ב:
          </p>
          <div className="flex flex-wrap gap-2">
            {dependencies.map((dep) => (
              <Badge key={dep.id} variant="secondary" className="gap-2">
                {dep.task_name}
                <span className="text-xs text-muted-foreground">
                  ({getDependencyTypeLabel(dep.dependency_type)})
                </span>
                <Button
                  variant="ghost"
                  size="sm"
                  className="h-4 w-4 p-0 hover:bg-transparent"
                  onClick={() => removeDependency.mutate(dep.id)}
                >
                  <X className="h-3 w-3" />
                </Button>
              </Badge>
            ))}
          </div>
        </div>
      )}

      {/* Add new dependency */}
      <div className="space-y-3 p-4 border rounded-lg bg-card">
        <Label>הוסף תלות חדשה</Label>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
          <Select value={selectedTaskId} onValueChange={setSelectedTaskId}>
            <SelectTrigger>
              <SelectValue placeholder="בחר משימה" />
            </SelectTrigger>
            <SelectContent>
              {availableTasks?.map((task) => (
                <SelectItem key={task.id} value={task.id}>
                  {task.name}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>

          <Select value={dependencyType} onValueChange={setDependencyType}>
            <SelectTrigger>
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="finish_to_start">סיום → התחלה</SelectItem>
              <SelectItem value="start_to_start">התחלה → התחלה</SelectItem>
              <SelectItem value="finish_to_finish">סיום → סיום</SelectItem>
            </SelectContent>
          </Select>
        </div>

        <Button
          onClick={() => addDependency.mutate()}
          disabled={!selectedTaskId || addDependency.isPending}
          className="w-full"
        >
          הוסף תלות
        </Button>
      </div>
    </div>
  );
}

import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { supabase } from '@/integrations/supabase/client';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { Checkbox } from '@/components/ui/checkbox';
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from '@/components/ui/alert-dialog';
import { useToast } from '@/hooks/use-toast';
import { Pencil, Trash2, Plus, CalendarIcon, Clock } from 'lucide-react';
import { Card, CardContent } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Calendar } from '@/components/ui/calendar';
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { cn } from '@/lib/utils';
import { format } from 'date-fns';
import { he } from 'date-fns/locale';
import { PriorityBadge } from './PriorityBadge';

interface Task {
  id: string;
  category_id: string;
  name: string;
  description: string | null;
  order_index: number;
  is_required: boolean;
  due_date?: string | null;
  estimated_hours?: number | null;
  priority?: "low" | "medium" | "high" | "urgent";
}

interface TaskManagementDialogProps {
  isOpen: boolean;
  onClose: () => void;
  categoryId: string;
  categoryName: string;
  tasks: Task[];
}

export const TaskManagementDialog = ({
  isOpen,
  onClose,
  categoryId,
  categoryName,
  tasks,
}: TaskManagementDialogProps) => {
  const { toast } = useToast();
  const queryClient = useQueryClient();
  const [editingTask, setEditingTask] = useState<Task | null>(null);
  const [deletingTaskId, setDeletingTaskId] = useState<string | null>(null);
  const [isAdding, setIsAdding] = useState(false);
  const [formData, setFormData] = useState({
    name: '',
    description: '',
    is_required: false,
    due_date: '',
    estimated_hours: '',
    priority: 'medium' as "low" | "medium" | "high" | "urgent",
  });

  const categoryTasks = tasks.filter((t) => t.category_id === categoryId);

  const createMutation = useMutation({
    mutationFn: async (data: typeof formData) => {
      const maxOrder = Math.max(...categoryTasks.map((t) => t.order_index), 0);
      const { error } = await supabase.from('tasks').insert({
        category_id: categoryId,
        name: data.name,
        description: data.description || null,
        is_required: data.is_required,
        order_index: maxOrder + 1,
        due_date: data.due_date || null,
        estimated_hours: data.estimated_hours ? parseInt(data.estimated_hours) : null,
        priority: data.priority,
      });
      if (error) throw error;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['tasks'] });
      toast({ title: 'המשימה נוספה בהצלחה' });
      setIsAdding(false);
      setFormData({ name: '', description: '', is_required: false, due_date: '', estimated_hours: '', priority: 'medium' });
    },
    onError: (error: Error) => {
      toast({ title: 'שגיאה', description: error.message, variant: 'destructive' });
    },
  });

  const updateMutation = useMutation({
    mutationFn: async (data: typeof formData & { id: string }) => {
      const { error } = await supabase
        .from('tasks')
        .update({
          name: data.name,
          description: data.description || null,
          is_required: data.is_required,
          due_date: data.due_date || null,
          estimated_hours: data.estimated_hours ? parseInt(data.estimated_hours) : null,
          priority: data.priority,
        })
        .eq('id', data.id);
      if (error) throw error;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['tasks'] });
      toast({ title: 'המשימה עודכנה בהצלחה' });
      setEditingTask(null);
    },
    onError: (error: Error) => {
      toast({ title: 'שגיאה', description: error.message, variant: 'destructive' });
    },
  });

  const deleteMutation = useMutation({
    mutationFn: async (id: string) => {
      const { error } = await supabase.from('tasks').delete().eq('id', id);
      if (error) throw error;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['tasks'] });
      toast({ title: 'המשימה נמחקה בהצלחה' });
      setDeletingTaskId(null);
    },
    onError: (error: Error) => {
      toast({ title: 'שגיאה', description: error.message, variant: 'destructive' });
    },
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingTask) {
      updateMutation.mutate({ ...formData, id: editingTask.id });
    } else {
      createMutation.mutate(formData);
    }
  };

  const startEdit = (task: Task) => {
    setEditingTask(task);
    setFormData({
      name: task.name,
      description: task.description || '',
      is_required: task.is_required,
      due_date: task.due_date || '',
      estimated_hours: task.estimated_hours?.toString() || '',
      priority: task.priority || 'medium',
    });
    setIsAdding(true);
  };

  return (
    <>
      <Dialog open={isOpen} onOpenChange={onClose}>
        <DialogContent className="max-w-2xl max-h-[80vh] overflow-y-auto" dir="rtl">
          <DialogHeader>
            <DialogTitle>ניהול משימות - {categoryName}</DialogTitle>
            <DialogDescription>הוסף, ערוך או מחק משימות בקטגוריה זו</DialogDescription>
          </DialogHeader>

          <div className="space-y-6">
            {!isAdding ? (
              <Button onClick={() => setIsAdding(true)} className="w-full">
                <Plus className="ml-2 h-4 w-4" />
                הוסף משימה חדשה
              </Button>
            ) : (
              <Card>
                <CardContent className="pt-6">
                  <form onSubmit={handleSubmit} className="space-y-4">
                    <div className="space-y-2">
                      <Label htmlFor="name">שם המשימה</Label>
                      <Input
                        id="name"
                        value={formData.name}
                        onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                        placeholder="הגשת תוכנית למחלקה לתכנון"
                        required
                      />
                    </div>
                    <div className="space-y-2">
                      <Label htmlFor="description">תיאור (אופציונלי)</Label>
                      <Textarea
                        id="description"
                        value={formData.description}
                        onChange={(e) =>
                          setFormData({ ...formData, description: e.target.value })
                        }
                        placeholder="פרטים נוספים על המשימה..."
                        rows={3}
                      />
                    </div>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                      <div className="space-y-2">
                        <Label>תאריך יעד</Label>
                        <Popover>
                          <PopoverTrigger asChild>
                            <Button
                              variant="outline"
                              className={cn(
                                "w-full justify-start text-right font-normal",
                                !formData.due_date && "text-muted-foreground"
                              )}
                            >
                              <CalendarIcon className="ml-2 h-4 w-4" />
                              {formData.due_date ? (
                                format(new Date(formData.due_date), "PPP", { locale: he })
                              ) : (
                                <span>בחר תאריך</span>
                              )}
                            </Button>
                          </PopoverTrigger>
                          <PopoverContent className="w-auto p-0" align="start">
                            <Calendar
                              mode="single"
                              selected={formData.due_date ? new Date(formData.due_date) : undefined}
                              onSelect={(date) => setFormData({ ...formData, due_date: date?.toISOString() || '' })}
                              locale={he}
                              initialFocus
                            />
                          </PopoverContent>
                        </Popover>
                      </div>

                      <div className="space-y-2">
                        <Label htmlFor="estimated_hours">שעות משוערות</Label>
                        <Input
                          id="estimated_hours"
                          type="number"
                          min="0"
                          value={formData.estimated_hours}
                          onChange={(e) => setFormData({ ...formData, estimated_hours: e.target.value })}
                          placeholder="0"
                        />
                      </div>
                    </div>

                    <div className="space-y-2">
                      <Label htmlFor="priority">עדיפות</Label>
                      <Select
                        value={formData.priority}
                        onValueChange={(value) => setFormData({ ...formData, priority: value as any })}
                      >
                        <SelectTrigger>
                          <SelectValue />
                        </SelectTrigger>
                        <SelectContent>
                          <SelectItem value="low">נמוכה</SelectItem>
                          <SelectItem value="medium">בינונית</SelectItem>
                          <SelectItem value="high">גבוהה</SelectItem>
                          <SelectItem value="urgent">דחוף</SelectItem>
                        </SelectContent>
                      </Select>
                    </div>

                    <div className="flex items-center gap-2">
                      <Checkbox
                        id="is_required"
                        checked={formData.is_required}
                        onCheckedChange={(checked) =>
                          setFormData({ ...formData, is_required: checked as boolean })
                        }
                      />
                      <Label htmlFor="is_required" className="cursor-pointer">
                        משימה חובה
                      </Label>
                    </div>
                    <div className="flex gap-2">
                      <Button type="submit" disabled={createMutation.isPending || updateMutation.isPending}>
                        {editingTask ? 'עדכן' : 'הוסף'}
                      </Button>
                      <Button
                        type="button"
                        variant="outline"
                        onClick={() => {
                          setIsAdding(false);
                          setEditingTask(null);
                          setFormData({ name: '', description: '', is_required: false, due_date: '', estimated_hours: '', priority: 'medium' });
                        }}
                      >
                        ביטול
                      </Button>
                    </div>
                  </form>
                </CardContent>
              </Card>
            )}

            <div className="space-y-2">
              <h3 className="font-semibold">משימות קיימות ({categoryTasks.length})</h3>
              {categoryTasks.length === 0 ? (
                <p className="text-sm text-muted-foreground text-center py-8">
                  אין משימות בקטגוריה זו
                </p>
              ) : (
                categoryTasks.map((task) => (
                  <Card key={task.id}>
                    <CardContent className="flex items-start justify-between p-4">
                      <div className="flex-1">
                        <div className="flex items-center gap-2 mb-1 flex-wrap">
                          <p className="font-medium">{task.name}</p>
                          {task.is_required && (
                            <Badge variant="outline" className="text-xs">
                              חובה
                            </Badge>
                          )}
                          {task.priority && (
                            <PriorityBadge priority={task.priority} className="text-xs" />
                          )}
                          {task.due_date && (
                            <Badge variant="secondary" className="text-xs gap-1">
                              <CalendarIcon className="h-3 w-3" />
                              {format(new Date(task.due_date), "d/M/yy", { locale: he })}
                            </Badge>
                          )}
                          {task.estimated_hours && (
                            <Badge variant="secondary" className="text-xs gap-1">
                              <Clock className="h-3 w-3" />
                              {task.estimated_hours}ש׳
                            </Badge>
                          )}
                        </div>
                        {task.description && (
                          <p className="text-sm text-muted-foreground">{task.description}</p>
                        )}
                      </div>
                      <div className="flex gap-2 ml-4">
                        <Button variant="ghost" size="sm" onClick={() => startEdit(task)}>
                          <Pencil className="h-4 w-4" />
                        </Button>
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => setDeletingTaskId(task.id)}
                        >
                          <Trash2 className="h-4 w-4 text-destructive" />
                        </Button>
                      </div>
                    </CardContent>
                  </Card>
                ))
              )}
            </div>
          </div>
        </DialogContent>
      </Dialog>

      <AlertDialog open={!!deletingTaskId} onOpenChange={() => setDeletingTaskId(null)}>
        <AlertDialogContent dir="rtl">
          <AlertDialogHeader>
            <AlertDialogTitle>האם אתה בטוח?</AlertDialogTitle>
            <AlertDialogDescription>
              פעולה זו תמחק את המשימה מכל הפרויקטים. לא ניתן לבטל פעולה זו.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>ביטול</AlertDialogCancel>
            <AlertDialogAction
              onClick={() => deletingTaskId && deleteMutation.mutate(deletingTaskId)}
            >
              מחק
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </>
  );
};

import { useState } from 'react';
