import { useToast } from '@/hooks/use-toast';

interface TaskTemplateOption {
  id: string;
  name: string;
  description: string;
}

const PREDEFINED_TEMPLATES: TaskTemplateOption[] = [
  { id: 'permit', name: 'משימות להיתר', description: 'רשימת משימות סטנדרטית לקבלת היתר בנייה' },
  { id: 'taba', name: 'משימות לשינוי תבע', description: 'רשימת משימות לתהליך שינוי בתבע' },
  { id: 'execution', name: 'משימות לביצוע', description: 'רשימת משימות למעקב ביצוע עבודות' },
  { id: 'custom', name: 'רשימה מותאמת אישית', description: 'צור רשימה חדשה או ייבא מקובץ' },
];

interface TaskTemplateState {
  templateType: string;
  customTemplateName: string;
  importedTasks: any[];
}

interface TaskTemplateSelectorProps {
  value: TaskTemplateState;
  onChange: (value: TaskTemplateState) => void;
}

export const TaskTemplateSelector = ({ value, onChange }: TaskTemplateSelectorProps) => {
  const { toast } = useToast();
  const [isImporting, setIsImporting] = useState(false);

  const handleFileImport = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsImporting(true);
    try {
      const text = await file.text();
      let tasks: any[] = [];

      const lowerName = file.name.toLowerCase();

      if (lowerName.endsWith('.xlsx') || lowerName.endsWith('.xls')) {
        // Parse Excel using xlsx
        const XLSX = await import('xlsx');
        const data = await file.arrayBuffer();
        const workbook = XLSX.read(data, { type: 'array' });
        const firstSheet = workbook.SheetNames[0];
        const sheet = workbook.Sheets[firstSheet];
        const rows: any[] = XLSX.utils.sheet_to_json(sheet, { defval: '' });
        if (rows.length > 0) {
          const firstKeys = Object.keys(rows[0] || {});
          tasks = rows.map((row, index) => ({
            name: row.name || row.title || (firstKeys.length ? row[firstKeys[0]] : '') || `משימה ${index + 1}`,
            description: row.description || row.desc || '',
          }));
        }
      } else if (lowerName.endsWith('.csv')) {
        // Parse CSV
        const lines = text.split('\n').filter(line => line.trim());
        const headers = lines[0].split(',').map(h => h.trim());
        tasks = lines.slice(1).map(line => {
          const values = line.split(',').map(v => v.trim());
          const task: any = {};
          headers.forEach((header, i) => {
            task[header] = values[i] || '';
          });
          return task;
        });
      } else if (lowerName.endsWith('.json')) {
        // Parse JSON
        tasks = JSON.parse(text);
      } else if (lowerName.endsWith('.txt')) {
        // Parse TXT - each line is a task name
        tasks = text
          .split('\n')
          .map(l => l.replace(/^[\uFEFF\u200B]+/, '')) // strip BOM/ZWSP
          .filter(line => line.trim())
          .map(line => ({ name: line.trim() }));
      } else if (lowerName.endsWith('.xml')) {
        // Basic XML parsing
        const parser = new DOMParser();
        const xml = parser.parseFromString(text, 'text/xml');
        const taskElements = xml.querySelectorAll('task');
        tasks = Array.from(taskElements).map((elem, index) => ({
          name: elem.getAttribute('name') || elem.textContent?.trim() || `משימה ${index + 1}`,
          description: elem.getAttribute('description') || '',
        }));
      }

      onChange({
        ...value,
        importedTasks: tasks,
      });

      toast({
        title: 'הקובץ יובא בהצלחה',
        description: `נמצאו ${tasks.length} משימות`,
      });
    } catch (error: any) {
      toast({
        title: 'שגיאה בייבוא הקובץ',
        description: error.message,
        variant: 'destructive',
      });
    } finally {
      setIsImporting(false);
    }
  };

  return (
    <Card>
      <CardHeader>
        <CardTitle>בחר תבנית משימות</CardTitle>
        <CardDescription>
          בחר תבנית קיימת או צור רשימת משימות חדשה
        </CardDescription>
      </CardHeader>
      <CardContent className="space-y-4">
        <RadioGroup
          value={value.templateType}
          onValueChange={(val) => onChange({ ...value, templateType: val })}
        >
          {PREDEFINED_TEMPLATES.map((template) => (
            <div key={template.id} className="flex items-start space-x-2 space-x-reverse">
              <RadioGroupItem value={template.id} id={template.id} />
              <Label htmlFor={template.id} className="flex-1 cursor-pointer">
                <div className="font-medium">{template.name}</div>
                <div className="text-sm text-muted-foreground">{template.description}</div>
              </Label>
            </div>
          ))}
        </RadioGroup>

        {value.templateType === 'custom' && (
          <div className="space-y-4 pt-4 border-t">
            <div className="space-y-2">
              <Label htmlFor="customTemplateName">שם הרשימה המותאמת</Label>
              <Input
                id="customTemplateName"
                value={value.customTemplateName}
                onChange={(e) => onChange({ ...value, customTemplateName: e.target.value })}
                placeholder="לדוגמה: משימות לפרויקט מיוחד"
              />
            </div>

            <div className="space-y-2">
              <Label>ייבוא משימות מקובץ</Label>
              <div className="flex items-center gap-2">
                <Button
                  type="button"
                  variant="outline"
                  className="w-full"
                  onClick={() => document.getElementById('file-import')?.click()}
                  disabled={isImporting}
                >
                  <FileUp className="ml-2 h-4 w-4" />
                  {isImporting ? 'מייבא...' : 'ייבא מקובץ (Excel, CSV, TXT, XML, JSON)'}
                </Button>
                <input
                  id="file-import"
                  type="file"
                  accept=".csv,.txt,.xml,.json,.xlsx,.xls"
                  onChange={handleFileImport}
                  className="hidden"
                />
              </div>
              {value.importedTasks.length > 0 && (
                <p className="text-sm text-muted-foreground">
                  {value.importedTasks.length} משימות נטענו
                </p>
              )}
            </div>
          </div>
        )}
      </CardContent>
    </Card>
  );
};

import { useQuery } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  ResponsiveContainer,
  PieChart,
  Pie,
  Cell,
} from "recharts";
import { Clock, TrendingUp, AlertCircle, CheckCircle } from "lucide-react";

interface TaskTimeAnalyticsProps {
  projectId: string;
}

export function TaskTimeAnalytics({ projectId }: TaskTimeAnalyticsProps) {
  const { data: projectTasks } = useQuery({
    queryKey: ["project-tasks-analytics", projectId],
    queryFn: async () => {
      const { data, error } = await supabase
        .from("project_tasks")
        .select(`
          *,
          tasks (
            name,
            estimated_hours,
            category_id,
            categories (name, display_name)
          )
        `)
        .eq("project_id", projectId);

      if (error) throw error;
      return data;
    },
  });

  // Calculate time comparison by category
  const categoryData = projectTasks?.reduce((acc: any[], task: any) => {
    const categoryName = task.tasks?.categories?.display_name || "ללא קטגוריה";
    const estimated = task.tasks?.estimated_hours || 0;
    const actual = task.actual_hours || 0;

    const existing = acc.find((item) => item.category === categoryName);
    if (existing) {
      existing.estimated += estimated;
      existing.actual += actual;
    } else {
      acc.push({ category: categoryName, estimated, actual });
    }
    return acc;
  }, []);

  // Calculate status distribution
  const statusData = projectTasks?.reduce(
    (acc: any, task: any) => {
      if (task.completed) {
        acc.find((s: any) => s.name === "הושלם").value++;
      } else if (
        task.due_date_override &&
        new Date(task.due_date_override) < new Date()
      ) {
        acc.find((s: any) => s.name === "באיחור").value++;
      } else {
        acc.find((s: any) => s.name === "בתהליך").value++;
      }
      return acc;
    },
    [
      { name: "הושלם", value: 0, color: "hsl(var(--chart-1))" },
      { name: "בתהליך", value: 0, color: "hsl(var(--chart-2))" },
      { name: "באיחור", value: 0, color: "hsl(var(--chart-3))" },
    ]
  );

  // Calculate KPIs
  const totalEstimated =
    projectTasks?.reduce(
      (sum, task: any) => sum + (task.tasks?.estimated_hours || 0),
      0
    ) || 0;
  const totalActual =
    projectTasks?.reduce((sum, task: any) => sum + (task.actual_hours || 0), 0) || 0;
  const completedTasks =
    projectTasks?.filter((task: any) => task.completed).length || 0;
  const totalTasks = projectTasks?.length || 0;
  const completionRate = totalTasks > 0 ? (completedTasks / totalTasks) * 100 : 0;

  return (
    <div className="space-y-6">
      {/* KPI Cards */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <Card>
          <CardHeader className="flex flex-row items-center justify-between pb-2">
            <CardTitle className="text-sm font-medium">שעות משוערות</CardTitle>
            <Clock className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{totalEstimated}h</div>
          </CardContent>
        </Card>

        <Card>
          <CardHeader className="flex flex-row items-center justify-between pb-2">
            <CardTitle className="text-sm font-medium">שעות בפועל</CardTitle>
            <TrendingUp className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{totalActual}h</div>
            <p className="text-xs text-muted-foreground">
              {totalEstimated > 0
                ? `${((totalActual / totalEstimated) * 100).toFixed(1)}% מהמשוער`
                : ""}
            </p>
          </CardContent>
        </Card>

        <Card>
          <CardHeader className="flex flex-row items-center justify-between pb-2">
            <CardTitle className="text-sm font-medium">אחוז השלמה</CardTitle>
            <CheckCircle className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{completionRate.toFixed(1)}%</div>
            <p className="text-xs text-muted-foreground">
              {completedTasks} מתוך {totalTasks} משימות
            </p>
          </CardContent>
        </Card>

        <Card>
          <CardHeader className="flex flex-row items-center justify-between pb-2">
            <CardTitle className="text-sm font-medium">סטייה</CardTitle>
            <AlertCircle className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">
              {totalEstimated > 0
                ? `${(((totalActual - totalEstimated) / totalEstimated) * 100).toFixed(1)}%`
                : "0%"}
            </div>
            <p className="text-xs text-muted-foreground">
              {totalActual > totalEstimated ? "חריגה" : "חיסכון"}
            </p>
          </CardContent>
        </Card>
      </div>

      {/* Charts */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {/* Time Comparison by Category */}
        <Card>
          <CardHeader>
            <CardTitle>השוואת זמנים לפי קטגוריה</CardTitle>
          </CardHeader>
          <CardContent>
            <ResponsiveContainer width="100%" height={300}>
              <BarChart data={categoryData}>
                <CartesianGrid strokeDasharray="3 3" />
                <XAxis dataKey="category" />
                <YAxis />
                <Tooltip />
                <Legend />
                <Bar dataKey="estimated" fill="hsl(var(--chart-1))" name="משוער" />
                <Bar dataKey="actual" fill="hsl(var(--chart-2))" name="בפועל" />
              </BarChart>
            </ResponsiveContainer>
          </CardContent>
        </Card>

        {/* Status Distribution */}
        <Card>
          <CardHeader>
            <CardTitle>התפלגות סטטוס משימות</CardTitle>
          </CardHeader>
          <CardContent>
            <ResponsiveContainer width="100%" height={300}>
              <PieChart>
                <Pie
                  data={statusData}
                  cx="50%"
                  cy="50%"
                  labelLine={false}
                  label={(entry) => `${entry.name}: ${entry.value}`}
                  outerRadius={80}
                  fill="#8884d8"
                  dataKey="value"
                >
                  {statusData?.map((entry: any, index: number) => (
                    <Cell key={`cell-${index}`} fill={entry.color} />
                  ))}
                </Pie>
                <Tooltip />
              </PieChart>
            </ResponsiveContainer>
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

