export const WorkflowCategories = ({ projectId }: WorkflowCategoriesProps) => {
  const { toast } = useToast();
  const queryClient = useQueryClient();
  const { isAdmin } = useIsAdmin();

  // Fetch project data for timeline
  const { data: projectData } = useQuery({
    queryKey: ['project', projectId],
    queryFn: async () => {
      const { data, error } = await supabase
        .from('projects')
        .select('*')
        .eq('id', projectId)
        .single();

      if (error) throw error;
      return data;
    },
    enabled: !!projectId,
  });
  const [notesDialogOpen, setNotesDialogOpen] = useState(false);
  const [categoryManagementOpen, setCategoryManagementOpen] = useState(false);
  const [taskManagementOpen, setTaskManagementOpen] = useState(false);
  const [editTaskDialogOpen, setEditTaskDialogOpen] = useState(false);
  const [selectedTaskForEdit, setSelectedTaskForEdit] = useState<Task | null>(null);
  const [reminderDialogOpen, setReminderDialogOpen] = useState(false);
  const [selectedTaskForReminder, setSelectedTaskForReminder] = useState<{
    projectTaskId: string;
    taskName: string;
  } | null>(null);
  const [selectedCategoryForTasks, setSelectedCategoryForTasks] = useState<{
    id: string;
    name: string;
  } | null>(null);
  const [selectedTask, setSelectedTask] = useState<{
    id: string;
    name: string;
    notes: string | null;
  } | null>(null);
  const [schedulerDialogOpen, setSchedulerDialogOpen] = useState(false);
  const [selectedTaskForScheduler, setSelectedTaskForScheduler] = useState<{
    projectTaskId: string;
    taskId: string;
    taskName: string;
  } | null>(null);
  const [activeView, setActiveView] = useState('tasks');

  const { activeReminders, dismissReminder } = useReminders();

  // Filter states
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedCategory, setSelectedCategory] = useState('all');
  const [requiredOnly, setRequiredOnly] = useState(false);
  const [statusFilter, setStatusFilter] = useState('all');

  const { data: categories } = useSyncedQuery({
    queryKey: ['categories'],
    queryFn: async () => {
      const { data, error } = await supabase
        .from('categories')
        .select('*')
        .order('order_index');

      if (error) throw error;
      return data as Category[];
    },
  });

  const { data: tasks } = useSyncedQuery({
    queryKey: ['tasks'],
    queryFn: async () => {
      const { data, error } = await supabase
        .from('tasks')
        .select('*')
        .order('order_index');

      if (error) throw error;
      return data as Task[];
    },
  });

  const { data: projectTasks } = useSyncedQuery({
    queryKey: ['project-tasks', projectId],
    queryFn: async () => {
      const { data, error } = await supabase
        .from('project_tasks')
        .select('*')
        .eq('project_id', projectId);

      if (error) throw error;
      return data as ProjectTask[];
    },
  });

  // Build a resilient view: include a pseudo "uncategorized" bucket for tasks that don't match any real category
  const ORPHAN_CATEGORY_ID = '__uncategorized__';
  const validCategoryIds = new Set((categories || []).map((c) => c.id));
  const orphanTasks = (tasks || []).filter((t) => !validCategoryIds.has(t.category_id));

  // Only add the pseudo category if we actually have orphaned tasks
  const augmentedCategories: Category[] = (categories || []).concat(
    orphanTasks.length > 0
      ? [{
          id: ORPHAN_CATEGORY_ID,
          name: 'uncategorized',
          display_name: 'ללא קטגוריה',
          order_index: 999,
          color: null,
        }]
      : []
  );

  // Helper to resolve tasks by category (handles the pseudo category too)
  const getTasksByCategory = (categoryId: string) => {
    if (!tasks) return [] as Task[];
    if (categoryId === ORPHAN_CATEGORY_ID) {
      return tasks.filter((t) => !validCategoryIds.has(t.category_id));
    }
    return tasks.filter((t) => t.category_id === categoryId);
  };

  const toggleTaskMutation = useMutation({
    mutationFn: async ({ taskId, completed }: { taskId: string; completed: boolean }) => {
      const now = new Date().toISOString();
      const { data: { user } } = await supabase.auth.getUser();

      const { error } = await supabase
        .from('project_tasks')
        .upsert({
          project_id: projectId,
          task_id: taskId,
          completed,
          status: completed ? 'completed' : 'pending',
          completed_at: completed ? now : null,
          completed_by: completed ? user?.id : null,
          started_at: completed ? now : undefined
        });

      if (error) throw error;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['project-tasks', projectId] });
      toast({
        title: 'עודכן בהצלחה',
        description: 'סטטוס המשימה עודכן',
      });
    },
    onError: (error) => {
      toast({
        title: 'שגיאה',
        description: error.message,
        variant: 'destructive',
      });
    },
  });

  // Delete task mutation
  const deleteTaskMutation = useMutation({
    mutationFn: async (taskId: string) => {
      // First, delete all project_tasks that reference this task
      const { error: projectTasksError } = await supabase
        .from('project_tasks')
        .delete()
        .eq('task_id', taskId);

      if (projectTasksError) throw projectTasksError;

      // Then delete the task itself
      const { error: taskError } = await supabase
        .from('tasks')
        .delete()
        .eq('id', taskId);

      if (taskError) throw taskError;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['tasks'] });
      queryClient.invalidateQueries({ queryKey: ['project-tasks', projectId] });
      toast({
        title: 'נמחק בהצלחה',
        description: 'המשימה נמחקה מהמערכת',
      });
    },
    onError: (error) => {
      toast({
        title: 'שגיאה במחיקה',
        description: error.message,
        variant: 'destructive',
      });
    },
  });

  // Update task mutation
  const updateTaskMutation = useMutation({
    mutationFn: async ({ taskId, updates }: { taskId: string; updates: Partial<Task> }) => {
      const { error } = await supabase
        .from('tasks')
        .update(updates)
        .eq('id', taskId);

      if (error) throw error;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['tasks'] });
      setEditTaskDialogOpen(false);
      setSelectedTaskForEdit(null);
      toast({
        title: 'עודכן בהצלחה',
        description: 'המשימה עודכנה',
      });
    },
    onError: (error) => {
      toast({
        title: 'שגיאה בעדכון',
        description: error.message,
        variant: 'destructive',
      });
    },
  });

  const isTaskCompleted = (taskId: string) => {
    return projectTasks?.find((pt) => pt.task_id === taskId)?.completed || false;
  };

  const getCategoryProgress = (categoryId: string) => {
    const categoryTasks = getTasksByCategory(categoryId);
    if (categoryTasks.length === 0) return 0;

    const completed = categoryTasks.filter((t) => isTaskCompleted(t.id)).length;
    return Math.round((completed / categoryTasks.length) * 100);
  };

  const handleOpenNotes = (projectTaskId: string, taskName: string, currentNotes: string | null) => {
    setSelectedTask({ id: projectTaskId, name: taskName, notes: currentNotes });
    setNotesDialogOpen(true);
  };

  const getProjectTaskId = (taskId: string) => {
    return projectTasks?.find((pt) => pt.task_id === taskId)?.id || '';
  };

  const getCategoriesWithTasks = () => {
    if (!augmentedCategories || !tasks || !projectTasks) return [] as (Category & { tasks: Task[]; projectTasks: ProjectTask[] })[];

    return augmentedCategories.map((category) => ({
      ...category,
      tasks: getTasksByCategory(category.id),
      projectTasks: projectTasks.filter((pt) =>
        tasks.some((t) => t.id === pt.task_id && (category.id === ORPHAN_CATEGORY_ID ? !validCategoryIds.has(t.category_id) : t.category_id === category.id))
      ),
    }));
  };

  // Filter functions
  const filterTasks = () => {
    if (!tasks) return [];

    return tasks.filter((task) => {
      // Search filter
      if (searchQuery && !task.name.toLowerCase().includes(searchQuery.toLowerCase())) {
        return false;
      }

      // Category filter
      if (selectedCategory !== 'all') {
        if (selectedCategory === ORPHAN_CATEGORY_ID) {
          if (validCategoryIds.has(task.category_id)) return false;
        } else if (task.category_id !== selectedCategory) {
          return false;
        }
      }

      // Required filter
      if (requiredOnly && !task.is_required) {
        return false;
      }

      // Status filter
      if (statusFilter !== 'all') {
        const isCompleted = isTaskCompleted(task.id);
        if (statusFilter === 'completed' && !isCompleted) return false;
        if (statusFilter === 'pending' && isCompleted) return false;
      }

      return true;
    });
  };

  const resetFilters = () => {
    setSearchQuery('');
    setSelectedCategory('all');
    setRequiredOnly(false);
    setStatusFilter('all');
  };

  const filteredTasks = filterTasks();

  if (!categories || !tasks) {
    return (
      <div className="space-y-4">
        {[...Array(4)].map((_, i) => (
          <Card key={i} className="animate-pulse">
            <CardHeader>
              <div className="h-6 bg-muted rounded w-1/3"></div>
            </CardHeader>
            <CardContent>
              <div className="space-y-2">
                <div className="h-4 bg-muted rounded"></div>
                <div className="h-4 bg-muted rounded w-5/6"></div>
              </div>
            </CardContent>
          </Card>
        ))}
      </div>
    );
  }

  const categoriesWithTasks = getCategoriesWithTasks();

  const handleOpenTaskManagement = (categoryId: string, categoryName: string) => {
    setSelectedCategoryForTasks({ id: categoryId, name: categoryName });
    setTaskManagementOpen(true);
  };

  return (
    <div className="space-y-6" dir="rtl">
      <OfflineIndicator />

      {isAdmin && (
        <div className="flex justify-start">
          <Button onClick={() => setCategoryManagementOpen(true)} variant="outline">
            <Settings className="mr-2 h-4 w-4" />
            ניהול קטגוריות
          </Button>
        </div>
      )}

      <TaskFilters
        searchQuery={searchQuery}
        onSearchChange={setSearchQuery}
        selectedCategory={selectedCategory}
        onCategoryChange={setSelectedCategory}
        requiredOnly={requiredOnly}
        onRequiredOnlyChange={setRequiredOnly}
        statusFilter={statusFilter}
        onStatusFilterChange={setStatusFilter}
        categories={augmentedCategories || []}
        totalResults={filteredTasks.length}
        onReset={resetFilters}
      />

      <Tabs defaultValue="list" className="w-full" dir="rtl">
        <TabsList className="hidden md:inline-flex h-auto items-center justify-center rounded-xl bg-gradient-to-r from-card to-card/80 backdrop-blur-sm shadow-lg border-2 border-primary/10 p-2 text-muted-foreground w-full flex-wrap gap-1">
          <TabsTrigger 
            value="dashboard" 
            className="flex-1 data-[state=active]:bg-gradient-to-r data-[state=active]:from-primary data-[state=active]:to-primary/90 data-[state=active]:text-primary-foreground data-[state=active]:shadow-glow transition-all duration-300 hover:scale-105 rounded-lg font-semibold py-2.5"
          >
            <BarChart3 className="h-4 w-4 ml-1" />
            דשבורד
          </TabsTrigger>
          <TabsTrigger 
            value="list" 
            className="flex-1 data-[state=active]:bg-gradient-to-r data-[state=active]:from-primary data-[state=active]:to-primary/90 data-[state=active]:text-primary-foreground data-[state=active]:shadow-glow transition-all duration-300 hover:scale-105 rounded-lg font-semibold py-2.5"
          >
            משימות
          </TabsTrigger>
          <TabsTrigger 
            value="kanban" 
            className="flex-1 data-[state=active]:bg-gradient-to-r data-[state=active]:from-primary data-[state=active]:to-primary/90 data-[state=active]:text-primary-foreground data-[state=active]:shadow-glow transition-all duration-300 hover:scale-105 rounded-lg font-semibold py-2.5"
          >
            <Map className="h-4 w-4 ml-1" />
            קנבן
          </TabsTrigger>
          <TabsTrigger 
            value="gantt" 
            className="flex-1 data-[state=active]:bg-gradient-to-r data-[state=active]:from-primary data-[state=active]:to-primary/90 data-[state=active]:text-primary-foreground data-[state=active]:shadow-glow transition-all duration-300 hover:scale-105 rounded-lg font-semibold py-2.5"
          >
            Gantt
          </TabsTrigger>
          <TabsTrigger 
            value="calendar" 
            className="flex-1 data-[state=active]:bg-gradient-to-r data-[state=active]:from-primary data-[state=active]:to-primary/90 data-[state=active]:text-primary-foreground data-[state=active]:shadow-glow transition-all duration-300 hover:scale-105 rounded-lg font-semibold py-2.5"
          >
            <CalendarIcon className="h-4 w-4 ml-1" />
            לוח שנה
          </TabsTrigger>
          <TabsTrigger 
            value="analytics" 
            className="flex-1 data-[state=active]:bg-gradient-to-r data-[state=active]:from-primary data-[state=active]:to-primary/90 data-[state=active]:text-primary-foreground data-[state=active]:shadow-glow transition-all duration-300 hover:scale-105 rounded-lg font-semibold py-2.5"
          >
            אנליטיקס
          </TabsTrigger>
          <TabsTrigger 
            value="time-tracking" 
            className="flex-1 data-[state=active]:bg-gradient-to-r data-[state=active]:from-primary data-[state=active]:to-primary/90 data-[state=active]:text-primary-foreground data-[state=active]:shadow-glow transition-all duration-300 hover:scale-105 rounded-lg font-semibold py-2.5"
          >
            <Clock className="h-4 w-4 ml-1" />
            מעקב זמנים
          </TabsTrigger>
          <TabsTrigger 
            value="timeline" 
            className="flex-1 data-[state=active]:bg-gradient-to-r data-[state=active]:from-primary data-[state=active]:to-primary/90 data-[state=active]:text-primary-foreground data-[state=active]:shadow-glow transition-all duration-300 hover:scale-105 rounded-lg font-semibold py-2.5"
          >
            ציר זמן
          </TabsTrigger>
          <TabsTrigger 
            value="roadmap" 
            className="flex-1 data-[state=active]:bg-gradient-to-r data-[state=active]:from-primary data-[state=active]:to-primary/90 data-[state=active]:text-primary-foreground data-[state=active]:shadow-glow transition-all duration-300 hover:scale-105 rounded-lg font-semibold py-2.5"
          >
            מפת דרך
          </TabsTrigger>
          <TabsTrigger 
            value="spreadsheet" 
            className="flex-1 data-[state=active]:bg-gradient-to-r data-[state=active]:from-primary data-[state=active]:to-primary/90 data-[state=active]:text-primary-foreground data-[state=active]:shadow-glow transition-all duration-300 hover:scale-105 rounded-lg font-semibold py-2.5"
          >
            <FileSpreadsheet className="h-4 w-4 ml-1" />
            טבלה
          </TabsTrigger>
          <TabsTrigger 
            value="export" 
            className="flex-1 data-[state=active]:bg-gradient-to-r data-[state=active]:from-primary data-[state=active]:to-primary/90 data-[state=active]:text-primary-foreground data-[state=active]:shadow-glow transition-all duration-300 hover:scale-105 rounded-lg font-semibold py-2.5"
          >
            <Download className="h-4 w-4 ml-1" />
            יצוא/יבוא
          </TabsTrigger>
        </TabsList>

        <MobileBottomNav activeTab={activeView} onTabChange={setActiveView} />

        <TabsContent value="dashboard" className="space-y-4">
          <ProjectDashboard projectId={projectId} />
        </TabsContent>

        <TabsContent value="gantt" className="space-y-4">
          <GanttView projectId={projectId} />
        </TabsContent>

        <TabsContent value="analytics" className="space-y-4">
          <TaskTimeAnalytics projectId={projectId} />
        </TabsContent>

        <TabsContent value="kanban" className="space-y-4">
          <KanbanBoard
            projectId={projectId}
            tasks={filteredTasks.map(task => ({
              id: task.id,
              name: task.name,
              status: projectTasks?.find(pt => pt.task_id === task.id)?.status || 'pending',
              priority: task.priority,
              dueDate: task.due_date || undefined,
            }))}
            allTasks={tasks}
            categories={augmentedCategories}
            onStatusChange={async (taskId, newStatus) => {
              const projectTask = projectTasks?.find(pt => pt.task_id === taskId);
              if (projectTask) {
                await supabase
                  .from('project_tasks')
                  .update({ status: newStatus })
                  .eq('id', projectTask.id);
                queryClient.invalidateQueries({ queryKey: ['project-tasks', projectId] });
              }
            }}
            onTaskClick={(task) => {
              setSelectedTask({ id: task.id, name: task.name, notes: null });
              setNotesDialogOpen(true);
            }}
          />
        </TabsContent>

        <TabsContent value="list" className="space-y-4">
          {augmentedCategories.map((category) => {
            const categoryTasks = filteredTasks.filter((t) =>
              category.id === ORPHAN_CATEGORY_ID ? !validCategoryIds.has(t.category_id) : t.category_id === category.id
            );
            if (categoryTasks.length === 0) return null;
            const progress = getCategoryProgress(category.id);

            return (
              <Card key={category.id}>
                <CardHeader>
                  <div className="flex items-center justify-between">
                    <div className="flex items-center gap-3">
                      {category.color && (
                        <div
                          className="w-3 h-3 rounded-full"
                          style={{ backgroundColor: category.color }}
                        />
                      )}
                      <CardTitle>{category.display_name}</CardTitle>
                      <Badge variant="secondary">{categoryTasks.length} משימות</Badge>
                      {isAdmin && category.id !== ORPHAN_CATEGORY_ID && (
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() =>
                            handleOpenTaskManagement(category.id, category.display_name)
                          }
                        >
                          <Settings className="h-4 w-4" />
                        </Button>
                      )}
                    </div>
                    <div className="flex items-center gap-2">
                      <span className="text-sm text-muted-foreground">{progress}%</span>
                      <div className="w-24 h-2 bg-muted rounded-full overflow-hidden">
                        <div
                          className="h-full bg-primary transition-all"
                          style={{ width: `${progress}%` }}
                        />
                      </div>
                    </div>
                  </div>
                </CardHeader>
                <CardContent>
                  <div className="space-y-3">
                    {categoryTasks.map((task) => {
                      const projectTask = projectTasks?.find((pt) => pt.task_id === task.id);
                      return (
                        <div
                          key={task.id}
                          className="flex items-start gap-3 p-3 rounded-lg hover:bg-accent/50 transition-colors group"
                        >
                          <Checkbox
                            checked={isTaskCompleted(task.id)}
                            onCheckedChange={(checked) =>
                              toggleTaskMutation.mutate({
                                taskId: task.id,
                                completed: checked as boolean,
                              })
                            }
                            className="mt-1"
                          />
                          <div className="flex-1 space-y-1">
                            <div className="flex items-center gap-2">
                              <span
                                className={`font-medium ${
                                  isTaskCompleted(task.id)
                                    ? 'line-through text-muted-foreground'
                                    : ''
                                }`}
                              >
                                {task.name}
                              </span>
                              {task.is_required && (
                                <Badge variant="outline" className="text-xs">
                                  חובה
                                </Badge>
                              )}
                            </div>
                            {task.description && (
                              <p className="text-sm text-muted-foreground">
                                {task.description}
                              </p>
                            )}
                          </div>
                           <div className="flex gap-1">
                            <Button
                              variant="ghost"
                              size="sm"
                              className="opacity-0 group-hover:opacity-100 transition-opacity"
                              onClick={() => {
                                setSelectedTaskForScheduler({
                                  projectTaskId: getProjectTaskId(task.id),
                                  taskId: task.id,
                                  taskName: task.name,
                                });
                                setSchedulerDialogOpen(true);
                              }}
                              title="תזמון משימה"
                            >
                              <Clock className="h-4 w-4" />
                            </Button>
                            <Button
                              variant="ghost"
                              size="sm"
                              className="opacity-0 group-hover:opacity-100 transition-opacity"
                              onClick={() => {
                                setSelectedTaskForReminder({
                                  projectTaskId: getProjectTaskId(task.id),
                                  taskName: task.name,
                                });
                                setReminderDialogOpen(true);
                              }}
                              title="הגדר תזכורת"
                            >
                              <Bell className="h-4 w-4" />
                            </Button>
                            <Button
                              variant="ghost"
                              size="sm"
                              className="opacity-0 group-hover:opacity-100 transition-opacity"
                              onClick={() =>
                                handleOpenNotes(
                                  getProjectTaskId(task.id),
                                  task.name,
                                  projectTask?.notes || null
                                )
                              }
                              title="הערות"
                            >
                              <MessageSquare className="h-4 w-4 ml-1" />
                              {projectTask?.notes && (
                                <Badge
                                  variant="secondary"
                                  className="mr-1 h-5 w-5 p-0 flex items-center justify-center rounded-full"
                                >
                                  ✓
                                </Badge>
                              )}
                            </Button>
                            {isAdmin && (
                              <>
                                <Button
                                  variant="ghost"
                                  size="sm"
                                  className="opacity-0 group-hover:opacity-100 transition-opacity text-muted-foreground hover:text-primary"
                                  onClick={() => {
                                    setSelectedTaskForEdit(task);
                                    setEditTaskDialogOpen(true);
                                  }}
                                  title="ערוך משימה"
                                >
                                  <Edit3 className="h-4 w-4" />
                                </Button>
                                <Button
                                  variant="ghost"
                                  size="sm"
                                  className="opacity-0 group-hover:opacity-100 transition-opacity text-muted-foreground hover:text-destructive"
                                  onClick={() => {
                                    if (confirm(`האם אתה בטוח שברצונך למחוק את המשימה "${task.name}"?`)) {
                                      deleteTaskMutation.mutate(task.id);
                                    }
                                  }}
                                  title="מחק משימה"
                                >
                                  <Trash2 className="h-4 w-4" />
                                </Button>
                              </>
                            )}
                          </div>
                        </div>
                      );
                    })}
                  </div>
                </CardContent>
              </Card>
            );
          })}
        </TabsContent>

        <TabsContent value="flow">
          <div className="overflow-x-auto pb-8">
            <div className="flex items-center gap-8 min-w-max px-4">
              {augmentedCategories.map((category, index) => {
                const categoryTasks = getTasksByCategory(category.id);
                const completedTasks = categoryTasks.filter((t) => isTaskCompleted(t.id)).length;
                const totalTasks = categoryTasks.length;
                const progress = totalTasks > 0 ? (completedTasks / totalTasks) * 100 : 0;
                const isCompleted = completedTasks === totalTasks && totalTasks > 0;

                return (
                  <div key={category.id} className="flex items-center gap-4">
                    <Card
                      className={`w-80 transition-all duration-500 hover:shadow-2xl hover:scale-105 ${
                        isCompleted ? 'border-primary shadow-lg shadow-primary/20' : ''
                      }`}
                      style={{
                        borderColor: isCompleted ? category.color || undefined : undefined,
                      }}
                    >
                      <CardHeader className="pb-3">
                        <div className="flex items-center justify-between">
                          <CardTitle className="text-xl">{category.display_name}</CardTitle>
                          {isCompleted && (
                            <CheckCircle2 className="h-6 w-6 text-primary animate-pulse" />
                          )}
                        </div>
                        <CardDescription>
                          {completedTasks} מתוך {totalTasks} משימות הושלמו
                        </CardDescription>
                      </CardHeader>
                      <CardContent>
                        <div className="space-y-4">
                          <div className="relative h-3 bg-muted rounded-full overflow-hidden">
                            <div
                              className="absolute top-0 right-0 h-full bg-gradient-to-l from-primary to-primary/70 transition-all duration-700 rounded-full"
                              style={{ width: `${progress}%` }}
                            />
                          </div>
                          <div className="space-y-2">
                            {categoryTasks.slice(0, 3).map((task) => (
                              <div key={task.id} className="flex items-center gap-2 text-sm">
                                <Checkbox
                                  checked={isTaskCompleted(task.id)}
                                  onCheckedChange={(checked) =>
                                    toggleTaskMutation.mutate({
                                      taskId: task.id,
                                      completed: checked as boolean,
                                    })
                                  }
                                />
                                <span
                                  className={
                                    isTaskCompleted(task.id)
                                      ? 'line-through text-muted-foreground'
                                      : ''
                                  }
                                >
                                  {task.name}
                                </span>
                              </div>
                            ))}
                            {categoryTasks.length > 3 && (
                              <p className="text-xs text-muted-foreground mr-6">
