                                  }
                                />
                                <span
                                  className={
                                    isTaskCompleted(task.id)
                                      ? 'line-through text-muted-foreground'
                                      : ''
                                  }
                                >
                                  {task.name}
                                </span>
                                {task.is_required && (
                                  <Badge variant="outline" className="mr-auto text-xs">
                                    חובה
                                  </Badge>
                                )}
                              </div>
                            ))}
                          </div>
                        </div>
                      </CardContent>
                    </Card>
                  </div>
                </div>
              );
            })}
          </div>
        </TabsContent>

        <TabsContent value="timeline">
          <TimelineView
            categories={augmentedCategories.map((category) => ({
              ...category,
              tasks: getTasksByCategory(category.id),
            }))}
            isTaskCompleted={isTaskCompleted}
            onToggleTask={(taskId, completed) =>
              toggleTaskMutation.mutate({ taskId, completed })
            }
          />
        </TabsContent>

        <TabsContent value="time-tracking">
          {projectData && categories && tasks && projectTasks && (
            <ProjectTimeline 
              project={projectData}
              categories={categories}
              allTasks={tasks}
              projectTasks={projectTasks}
            />
          )}
        </TabsContent>

        <TabsContent value="calendar">
          <CalendarView
            categories={augmentedCategories.map((category) => ({
              ...category,
              tasks: getTasksByCategory(category.id),
            }))}
            projectTasks={projectTasks || []}
            isTaskCompleted={isTaskCompleted}
          />
        </TabsContent>

        <TabsContent value="roadmap">
          <RoadmapView 
            categories={categoriesWithTasks} 
            projectId={projectId}
            tasks={tasks}
          />
        </TabsContent>

        <TabsContent value="spreadsheet" className="mt-6">
          <SpreadsheetView projectId={projectId} />
        </TabsContent>

        <TabsContent value="export" className="mt-6">
          <ExportImport projectId={projectId} />
        </TabsContent>

        <TabsContent value="backup" className="mt-6">
          <BackupRestore projectId={projectId} />
        </TabsContent>
      </Tabs>

      {/* Active Reminders */}
      {activeReminders.map((reminder) => (
        <ReminderNotification
          key={reminder.id}
          message={reminder.message || "הגיע הזמן!"}
          soundUrl={reminder.sound_url}
          onDismiss={() => dismissReminder(reminder.id)}
        />
      ))}

      {selectedTask && (
        <TaskNotesDialog
          projectTaskId={selectedTask.id}
          currentNotes={selectedTask.notes}
          taskName={selectedTask.name}
          isOpen={notesDialogOpen}
          onClose={() => {
            setNotesDialogOpen(false);
            setSelectedTask(null);
          }}
        />
      )}

      {selectedTaskForReminder && (
        <ReminderManager
          projectTaskId={selectedTaskForReminder.projectTaskId}
          taskName={selectedTaskForReminder.taskName}
          isOpen={reminderDialogOpen}
          onClose={() => {
            setReminderDialogOpen(false);
            setSelectedTaskForReminder(null);
          }}
        />
      )}

      {isAdmin && categories && (
        <CategoryManagementDialog
          isOpen={categoryManagementOpen}
          onClose={() => setCategoryManagementOpen(false)}
          categories={categories}
        />
      )}

      {isAdmin && selectedCategoryForTasks && tasks && (
        <TaskManagementDialog
          isOpen={taskManagementOpen}
          onClose={() => {
            setTaskManagementOpen(false);
            setSelectedCategoryForTasks(null);
          }}
          categoryId={selectedCategoryForTasks.id}
          categoryName={selectedCategoryForTasks.name}
          tasks={tasks}
        />
      )}

      {selectedTaskForScheduler && (
        <Dialog open={schedulerDialogOpen} onOpenChange={setSchedulerDialogOpen}>
          <DialogContent className="max-w-3xl max-h-[90vh] overflow-y-auto">
            <DialogHeader>
              <DialogTitle>תזמון משימה: {selectedTaskForScheduler.taskName}</DialogTitle>
            </DialogHeader>
            <TaskScheduler
              projectId={projectId}
              taskId={selectedTaskForScheduler.taskId}
              taskName={selectedTaskForScheduler.taskName}
              currentDueDate={
                projectTasks?.find((pt) => pt.id === selectedTaskForScheduler.projectTaskId)
                  ?.due_date_override || undefined
              }
              currentStartedAt={
                projectTasks?.find((pt) => pt.id === selectedTaskForScheduler.projectTaskId)
                  ?.started_at || undefined
              }
              currentEstimatedHours={
                tasks?.find((t) => t.id === selectedTaskForScheduler.taskId)?.estimated_hours ||
                undefined
              }
              currentActualHours={
                projectTasks?.find((pt) => pt.id === selectedTaskForScheduler.projectTaskId)
                  ?.actual_hours || undefined
              }
              currentProgress={
                (projectTasks?.find((pt) => pt.id === selectedTaskForScheduler.projectTaskId) as any)
                  ?.progress || 0
              }
              currentAssignedTo={
                (projectTasks?.find((pt) => pt.id === selectedTaskForScheduler.projectTaskId) as any)
                  ?.assigned_to || undefined
              }
              currentPriority={
                tasks?.find((t) => t.id === selectedTaskForScheduler.taskId)?.priority
              }
              onUpdate={async (data) => {
                const { error } = await supabase
                  .from('project_tasks')
                  .update(data)
                  .eq('id', selectedTaskForScheduler.projectTaskId);

                if (error) {
                  toast({
                    title: 'שגיאה',
                    description: error.message,
                    variant: 'destructive',
                  });
                } else {
                  queryClient.invalidateQueries({ queryKey: ['project-tasks', projectId] });
                  toast({
                    title: 'עודכן בהצלחה',
                    description: 'תזמון המשימה עודכן',
                  });
                  setSchedulerDialogOpen(false);
                  setSelectedTaskForScheduler(null);
                }
              }}
            />
          </DialogContent>
        </Dialog>
      )}

      {/* Edit Task Dialog */}
      <Dialog open={editTaskDialogOpen} onOpenChange={setEditTaskDialogOpen}>
        <DialogContent className="sm:max-w-[500px]">
          <DialogHeader>
            <DialogTitle>ערוך משימה</DialogTitle>
          </DialogHeader>
          {selectedTaskForEdit && (
            <div className="space-y-4">
              <div>
                <label htmlFor="edit-task-name" className="text-sm font-medium">שם המשימה</label>
                <input
                  type="text"
                  className="w-full mt-1 px-3 py-2 border rounded-md"
                  defaultValue={selectedTaskForEdit.name}
                  id="edit-task-name"
                  placeholder="הכנס שם משימה"
                />
              </div>
              <div>
                <label htmlFor="edit-task-description" className="text-sm font-medium">תיאור</label>
                <textarea
                  className="w-full mt-1 px-3 py-2 border rounded-md min-h-[100px]"
                  defaultValue={selectedTaskForEdit.description || ''}
                  id="edit-task-description"
                  placeholder="הוסף תיאור למשימה"
                />
              </div>
              <div className="flex items-center gap-2">
                <input
                  type="checkbox"
                  className="mt-1"
                  defaultChecked={selectedTaskForEdit.is_required}
                  id="edit-task-required"
                />
                <label htmlFor="edit-task-required" className="text-sm font-medium">חובה</label>
              </div>
              <div>
                <label htmlFor="edit-task-hours" className="text-sm font-medium">שעות משוערות</label>
                <input
                  type="number"
                  className="w-full mt-1 px-3 py-2 border rounded-md"
                  defaultValue={selectedTaskForEdit.estimated_hours || ''}
                  id="edit-task-hours"
                  min="0"
                  step="0.5"
                  placeholder="מספר שעות"
                />
              </div>
              <div className="flex gap-2 justify-end">
                <Button
                  variant="outline"
                  onClick={() => {
                    setEditTaskDialogOpen(false);
                    setSelectedTaskForEdit(null);
                  }}
                >
                  ביטול
                </Button>
                <Button
                  onClick={() => {
                    const name = (document.getElementById('edit-task-name') as HTMLInputElement).value;
                    const description = (document.getElementById('edit-task-description') as HTMLTextAreaElement).value;
                    const isRequired = (document.getElementById('edit-task-required') as HTMLInputElement).checked;
                    const estimatedHours = parseFloat((document.getElementById('edit-task-hours') as HTMLInputElement).value) || null;

                    updateTaskMutation.mutate({
                      taskId: selectedTaskForEdit.id,
                      updates: {
                        name,
                        description: description || null,
                        is_required: isRequired,
                        estimated_hours: estimatedHours,
                      },
                    });
                  }}
                >
                  שמור שינויים
                </Button>
              </div>
            </div>
          )}
        </DialogContent>
      </Dialog>
    </div>
  );
};

import { useQuery } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { format, differenceInDays, addDays } from "date-fns";
import { he } from "date-fns/locale";
import { cn } from "@/lib/utils";

interface GanttViewProps {
  projectId: string;
}

export function GanttView({ projectId }: GanttViewProps) {
  const { data: projectTasks, isLoading } = useQuery({
    queryKey: ["project-tasks-gantt", projectId],
    queryFn: async () => {
      const { data, error } = await supabase
        .from("project_tasks")
        .select(`
          *,
          tasks (
            name,
            priority,
            category_id,
            categories (name, display_name, color)
          )
        `)
        .eq("project_id", projectId)
        .not("started_at", "is", null)
        .not("due_date_override", "is", null)
        .order("started_at");

      if (error) throw error;
      return data;
    },
  });

  if (isLoading) {
    return <div className="text-center p-8">טוען...</div>;
  }

  if (!projectTasks || projectTasks.length === 0) {
    return (
      <Card>
        <CardContent className="p-8 text-center text-muted-foreground">
          אין משימות עם תאריכי התחלה וסיום מוגדרים
        </CardContent>
      </Card>
    );
  }

  // Calculate timeline boundaries
  const allDates = projectTasks.flatMap((task: any) => [
    new Date(task.started_at),
    new Date(task.due_date_override),
  ]);
  const minDate = new Date(Math.min(...allDates.map((d) => d.getTime())));
  const maxDate = new Date(Math.max(...allDates.map((d) => d.getTime())));
  const totalDays = differenceInDays(maxDate, minDate) + 1;

  // Generate week markers
  const weeks = [];
  let currentWeekStart = minDate;
  while (currentWeekStart <= maxDate) {
    weeks.push(currentWeekStart);
    currentWeekStart = addDays(currentWeekStart, 7);
  }

  const getPriorityColor = (priority: string) => {
    switch (priority) {
      case "urgent":
        return "bg-red-500";
      case "high":
        return "bg-orange-500";
      case "medium":
        return "bg-yellow-500";
      case "low":
        return "bg-blue-500";
      default:
        return "bg-gray-500";
    }
  };

  const getTaskPosition = (startDate: string, dueDate: string) => {
    const start = new Date(startDate);
    const end = new Date(dueDate);
    const startOffset = differenceInDays(start, minDate);
    const duration = differenceInDays(end, start) + 1;

    return {
      left: `${(startOffset / totalDays) * 100}%`,
      width: `${(duration / totalDays) * 100}%`,
    };
  };

  const today = new Date();
  const todayPosition = differenceInDays(today, minDate);
  const todayPercent = (todayPosition / totalDays) * 100;

  return (
    <Card>
      <CardHeader>
        <CardTitle className="flex items-center gap-2">
          תצוגת Gantt - לוח זמנים
        </CardTitle>
      </CardHeader>
      <CardContent>
        <div className="overflow-x-auto">
          <div className="min-w-[800px]">
            {/* Timeline header */}
            <div className="relative h-12 border-b mb-4">
              <div className="flex h-full">
                {weeks.map((week, index) => (
                  <div
                    key={index}
                    className="flex-1 text-center text-xs text-muted-foreground border-l p-1"
                  >
                    {format(week, "dd/MM", { locale: he })}
                  </div>
                ))}
              </div>
              {/* Today marker */}
              {todayPercent >= 0 && todayPercent <= 100 && (
                <div
                  className="absolute top-0 bottom-0 w-0.5 bg-red-500 z-10"
                  style={{ left: `${todayPercent}%` }}
                >
                  <div className="absolute -top-1 left-1/2 -translate-x-1/2 text-xs text-red-500 whitespace-nowrap">
                    היום
                  </div>
                </div>
              )}
            </div>

            {/* Tasks */}
            <div className="space-y-2">
              {projectTasks.map((task: any) => {
                const position = getTaskPosition(
                  task.started_at,
                  task.due_date_override
                );
                const isOverdue =
                  !task.completed &&
                  new Date(task.due_date_override) < new Date();

                return (
                  <div key={task.id} className="relative h-12">
                    {/* Task name */}
                    <div className="absolute left-0 top-1/2 -translate-y-1/2 w-48 pr-2 text-sm truncate">
                      {task.tasks?.name}
                    </div>

                    {/* Task bar */}
                    <div className="relative h-full pr-52">
                      <div
                        className={cn(
                          "absolute top-1/2 -translate-y-1/2 h-8 rounded-lg shadow-sm cursor-pointer transition-all hover:shadow-md",
                          getPriorityColor(task.tasks?.priority || "medium"),
                          task.completed && "opacity-50",
                          isOverdue && !task.completed && "ring-2 ring-red-500"
                        )}
                        style={position}
                      >
                        <div className="h-full flex items-center justify-center px-2">
                          <span className="text-xs text-white font-medium truncate">
                            {task.progress}%
                          </span>
                        </div>
                        {/* Progress overlay */}
                        {task.progress > 0 && task.progress < 100 && (
                          <div
                            className="absolute top-0 right-0 bottom-0 bg-white/30 rounded-r-lg"
                            style={{ width: `${100 - task.progress}%` }}
                          />
                        )}
                      </div>
                    </div>
                  </div>
                );
              })}
            </div>

            {/* Legend */}
            <div className="mt-6 pt-4 border-t flex flex-wrap gap-4 text-xs">
              <div className="flex items-center gap-2">
                <div className="w-3 h-3 rounded bg-red-500" />
                <span>דחוף</span>
              </div>
              <div className="flex items-center gap-2">
                <div className="w-3 h-3 rounded bg-orange-500" />
                <span>גבוה</span>
              </div>
              <div className="flex items-center gap-2">
                <div className="w-3 h-3 rounded bg-yellow-500" />
                <span>בינוני</span>
              </div>
              <div className="flex items-center gap-2">
                <div className="w-3 h-3 rounded bg-blue-500" />
                <span>נמוך</span>
              </div>
              <div className="flex items-center gap-2">
                <div className="w-0.5 h-3 bg-red-500" />
                <span>היום</span>
              </div>
            </div>
          </div>
        </div>
      </CardContent>
    </Card>
  );
}

import { useState } from 'react';
import { CheckCircle2, Circle, ChevronLeft, Plus, Edit, Bell } from 'lucide-react';
import { Card } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { TaskManagementDialog } from '../TaskManagementDialog';
import { CategoryManagementDialog } from '../CategoryManagementDialog';
import { ReminderManager } from '@/components/reminders/ReminderManager';
import { useIsAdmin } from '@/hooks/useIsAdmin';
import { useQuery } from '@tanstack/react-query';
import { supabase } from '@/integrations/supabase/client';
import { cn } from '@/lib/utils';

interface Task {
  id: string;
  name: string;
  description: string | null;
  is_required: boolean;
  order_index: number;
}

interface ProjectTask {
  id: string;
  task_id: string;
  completed: boolean;
  notes: string | null;
  status: string;
}

interface Category {
  id: string;
  name: string;
  display_name: string;
  color: string | null;
  order_index: number;
  tasks: Task[];
  projectTasks: ProjectTask[];
}

interface RoadmapViewProps {
  categories: Category[];
  projectId: string;
  tasks: any[];
}

export function RoadmapView({ categories, projectId, tasks }: RoadmapViewProps) {
  const { isAdmin } = useIsAdmin();
  const [taskDialogOpen, setTaskDialogOpen] = useState(false);
  const [categoryDialogOpen, setCategoryDialogOpen] = useState(false);
  const [selectedCategoryId, setSelectedCategoryId] = useState('');
  const [reminderDialogOpen, setReminderDialogOpen] = useState(false);
  const [selectedProjectTaskId, setSelectedProjectTaskId] = useState<string | null>(null);

  const { data: projectTasks = [] } = useQuery({
    queryKey: ['project-tasks', projectId],
    queryFn: async () => {
      const { data, error } = await supabase
        .from('project_tasks')
        .select('*')
        .eq('project_id', projectId);
      if (error) throw error;
      return data;
    },
  });
  // Get project-specific tasks for a category
  const getProjectCategoryTasks = (category: Category) => {
    return category.tasks.filter(task => 
      projectTasks?.some(pt => pt.task_id === task.id)
    );
  };

  const getCategoryProgress = (category: Category) => {
    const categoryTasks = getProjectCategoryTasks(category);
    const categoryProjectTasks = projectTasks?.filter((pt) =>
      categoryTasks.some((t) => t.id === pt.task_id)
    ) || [];
    const completedTasks = categoryProjectTasks.filter(
      (pt) => pt.completed
    ).length;
    const totalTasks = categoryTasks.length;
    return { completed: completedTasks, total: totalTasks };
  };

  const isCategoryCompleted = (category: Category) => {
    const { completed, total } = getCategoryProgress(category);
    return completed === total && total > 0;
  };

  return (
    <div className="py-12 px-4">
      <div className="max-w-6xl mx-auto">
        <div className="text-center mb-8">
          <h2 className="text-4xl font-bold mb-4">מפת דרך הפרויקט</h2>
          <p className="text-lg text-muted-foreground mb-6">
            מעקב אחר התקדמות הפרויקט שלב אחר שלב
          </p>

          {isAdmin && (
            <div className="flex justify-center gap-2 flex-wrap">
              <Button onClick={() => setCategoryDialogOpen(true)} variant="outline" size="sm">
                <Plus className="h-4 w-4 ml-1" />
                הוסף קטגוריה
              </Button>
            </div>
          )}
        </div>

        <div className="relative">
          {/* Vertical connecting line */}
          <div className="absolute right-1/2 top-0 bottom-0 w-1 bg-gradient-to-b from-primary via-primary/50 to-primary/20 transform translate-x-1/2 hidden md:block" />

          <div className="space-y-24">
            {categories.map((category, index) => {
              const isCompleted = isCategoryCompleted(category);
              const progress = getCategoryProgress(category);
              const isLeft = index % 2 === 0;

              return (
                <div
                  key={category.id}
                  className={`relative flex items-center ${
                    isLeft ? 'md:flex-row' : 'md:flex-row-reverse'
                  } flex-col gap-8`}
                >
                  {/* Milestone circle */}
                  <div className="relative z-10 flex-shrink-0 w-24 h-24 md:w-32 md:h-32">
                    <div
                      className={`w-full h-full rounded-full border-8 flex items-center justify-center transition-all duration-500 ${
                        isCompleted
                          ? 'bg-primary border-primary shadow-lg shadow-primary/50 scale-110'
                          : 'bg-card border-border'
                      }`}
                      style={{
                        borderColor: category.color || undefined,
                      }}
                    >
                      {isCompleted ? (
                        <CheckCircle2 className="w-12 h-12 md:w-16 md:h-16 text-primary-foreground" />
                      ) : (
                        <Circle className="w-12 h-12 md:w-16 md:h-16 text-muted-foreground" />
                      )}
                    </div>

                    {/* Step number badge */}
                    <div className="absolute -top-2 -right-2 w-10 h-10 bg-primary text-primary-foreground rounded-full flex items-center justify-center font-bold text-lg shadow-lg">
                      {index + 1}
                    </div>
                  </div>

                  {/* Connector arrow */}
                  <div className="hidden md:flex items-center flex-shrink-0">
                    <ChevronLeft
                      className={`w-8 h-8 text-primary ${
                        isLeft ? 'rotate-0' : 'rotate-180'
                      }`}
                    />
                  </div>

                  {/* Category card */}
                  <Card
                    className={`flex-1 p-8 transition-all duration-500 hover:shadow-xl ${
                      isCompleted ? 'border-primary/50 shadow-lg' : ''
                    }`}
                  >
                    <div className="space-y-4">
                      <div className="flex items-start justify-between gap-4">
                        <div>
                          <h3 className="text-2xl font-bold mb-2">
                            {category.display_name}
                          </h3>
                          <div className="flex items-center gap-2 flex-wrap">
                            <Badge
                              variant={isCompleted ? 'default' : 'outline'}
                              className="text-base px-3 py-1"
                            >
                              {progress.completed} מתוך {progress.total} משימות
                            </Badge>
                            {isCompleted && (
                              <Badge className="bg-primary text-primary-foreground">
                                הושלם ✓
                              </Badge>
                            )}
                          </div>
                        </div>

                        {isAdmin && (
                          <Button 
                            variant="outline" 
                            size="sm"
                            onClick={() => {
                              setSelectedCategoryId(category.id);
                              setTaskDialogOpen(true);
                            }}
                          >
                            <Edit className="h-4 w-4 ml-1" />
                            ערוך משימות
                          </Button>
                        )}
                      </div>

                      {/* Progress bar */}
                      <div className="w-full bg-muted rounded-full h-3 overflow-hidden">
                        <div
                          className="h-full bg-gradient-to-l from-primary to-primary/70 transition-all duration-700 rounded-full"
                          style={{
                            width: `${
                              progress.total > 0
                                ? (progress.completed / progress.total) * 100
                                : 0
                            }%`,
                          }}
                        />
                      </div>

                  {/* Tasks summary - All project tasks */}
                  <div className="grid gap-2 mt-4">
                    {getProjectCategoryTasks(category).map((task) => {
                      const projectTask = projectTasks?.find(
                        (pt) => pt.task_id === task.id
                      );
                      return (
                        <div
                          key={task.id}
                          className="flex items-center gap-3 text-sm group"
                        >
                          <div
                            className={cn(
                              "h-2 w-2 rounded-full flex-shrink-0",
                              projectTask?.completed
                                ? "bg-primary"
                                : "bg-muted-foreground/30"
                            )}
                          />
                          <span
                            className={cn(
                              "flex-1 text-right",
                              projectTask?.completed &&
                                "line-through text-muted-foreground"
                            )}
                          >
                            {task.name}
                          </span>
                          {task.is_required && (
                            <Badge variant="secondary" className="text-xs">
                              נדרש
                            </Badge>
                          )}
                          {projectTask && (
                            <Button
                              variant="ghost"
                              size="sm"
                              className="h-6 w-6 p-0 opacity-0 group-hover:opacity-100 transition-opacity"
                              onClick={(e) => {
                                e.stopPropagation();
                                setSelectedProjectTaskId(projectTask.id);
                                setReminderDialogOpen(true);
                              }}
                            >
                              <Bell className="h-3 w-3" />
                            </Button>
                          )}
                        </div>
                      );
                    })}
                  </div>
                    </div>
                  </Card>
                </div>
              );
            })}
          </div>
        </div>

        {/* Summary footer */}
        <div className="mt-24 text-center">
          <Card className="p-8 bg-gradient-to-bl from-primary/5 to-transparent border-primary/20">
            <h3 className="text-2xl font-bold mb-4">סיכום התקדמות</h3>
            <div className="flex justify-center gap-8 flex-wrap">
              <div className="text-center">
                <div className="text-4xl font-bold text-primary mb-2">
                  {categories.filter(isCategoryCompleted).length}
                </div>
                <div className="text-sm text-muted-foreground">
                  קטגוריות הושלמו
                </div>
              </div>
              <div className="text-center">
                <div className="text-4xl font-bold text-muted-foreground mb-2">
