import * as React from "react";

import type { ToastActionElement, ToastProps } from "@/components/ui/toast";

const TOAST_LIMIT = 1;
const TOAST_REMOVE_DELAY = 1000000;

type ToasterToast = ToastProps & {
  id: string;
  title?: React.ReactNode;
  description?: React.ReactNode;
  action?: ToastActionElement;
};

const actionTypes = {
  ADD_TOAST: "ADD_TOAST",
  UPDATE_TOAST: "UPDATE_TOAST",
  DISMISS_TOAST: "DISMISS_TOAST",
  REMOVE_TOAST: "REMOVE_TOAST",
} as const;

let count = 0;

function genId() {
  count = (count + 1) % Number.MAX_SAFE_INTEGER;
  return count.toString();
}

type ActionType = typeof actionTypes;

type Action =
  | {
      type: ActionType["ADD_TOAST"];
      toast: ToasterToast;
    }
  | {
      type: ActionType["UPDATE_TOAST"];
      toast: Partial<ToasterToast>;
    }
  | {
      type: ActionType["DISMISS_TOAST"];
      toastId?: ToasterToast["id"];
    }
  | {
      type: ActionType["REMOVE_TOAST"];
      toastId?: ToasterToast["id"];
    };

interface State {
  toasts: ToasterToast[];
}

const toastTimeouts = new Map<string, ReturnType<typeof setTimeout>>();

const addToRemoveQueue = (toastId: string) => {
  if (toastTimeouts.has(toastId)) {
    return;
  }

  const timeout = setTimeout(() => {
    toastTimeouts.delete(toastId);
    dispatch({
      type: "REMOVE_TOAST",
      toastId: toastId,
    });
  }, TOAST_REMOVE_DELAY);

  toastTimeouts.set(toastId, timeout);
};

export const reducer = (state: State, action: Action): State => {
  switch (action.type) {
    case "ADD_TOAST":
      return {
        ...state,
        toasts: [action.toast, ...state.toasts].slice(0, TOAST_LIMIT),
      };

    case "UPDATE_TOAST":
      return {
        ...state,
        toasts: state.toasts.map((t) => (t.id === action.toast.id ? { ...t, ...action.toast } : t)),
      };

    case "DISMISS_TOAST": {
      const { toastId } = action;

      // ! Side effects ! - This could be extracted into a dismissToast() action,
      // but I'll keep it here for simplicity
      if (toastId) {
        addToRemoveQueue(toastId);
      } else {
        state.toasts.forEach((toast) => {
          addToRemoveQueue(toast.id);
        });
      }

      return {
        ...state,
        toasts: state.toasts.map((t) =>
          t.id === toastId || toastId === undefined
            ? {
                ...t,
                open: false,
              }
            : t,
        ),
      };
    }
    case "REMOVE_TOAST":
      if (action.toastId === undefined) {
        return {
          ...state,
          toasts: [],
        };
      }
      return {
        ...state,
        toasts: state.toasts.filter((t) => t.id !== action.toastId),
      };
  }
};

const listeners: Array<(state: State) => void> = [];

let memoryState: State = { toasts: [] };

function dispatch(action: Action) {
  memoryState = reducer(memoryState, action);
  listeners.forEach((listener) => {
    listener(memoryState);
  });
}

type Toast = Omit<ToasterToast, "id">;

function toast({ ...props }: Toast) {
  const id = genId();

  const update = (props: ToasterToast) =>
    dispatch({
      type: "UPDATE_TOAST",
      toast: { ...props, id },
    });
  const dismiss = () => dispatch({ type: "DISMISS_TOAST", toastId: id });

  dispatch({
    type: "ADD_TOAST",
    toast: {
      ...props,
      id,
      open: true,
      onOpenChange: (open) => {
        if (!open) dismiss();
      },
    },
  });

  return {
    id: id,
    dismiss,
    update,
  };
}

function useToast() {
  const [state, setState] = React.useState<State>(memoryState);

  React.useEffect(() => {
    listeners.push(setState);
    return () => {
      const index = listeners.indexOf(setState);
      if (index > -1) {
        listeners.splice(index, 1);
      }
    };
  }, []);

  return {
    ...state,
    toast,
    dismiss: (toastId?: string) => dispatch({ type: "DISMISS_TOAST", toastId }),
  };
}

export { useToast, toast };

import { useEffect, useState } from "react";
import { useQuery } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";

interface ActiveReminder {
  id: string;
  message: string | null;
  sound_url: string | null;
  project_task_id: string;
}

export function useReminders() {
  const [activeReminders, setActiveReminders] = useState<ActiveReminder[]>([]);

  // Fetch active reminders that should trigger now
  const { data: reminders } = useQuery({
    queryKey: ["active-reminders"],
    queryFn: async () => {
      const now = new Date();
      const fiveMinutesAgo = new Date(now.getTime() - 5 * 60 * 1000);

      const { data, error } = await supabase
        .from("task_reminders")
        .select("id, message, sound_url, project_task_id, reminder_time")
        .eq("is_active", true)
        .gte("reminder_time", fiveMinutesAgo.toISOString())
        .lte("reminder_time", now.toISOString());

      if (error) throw error;
      return data;
    },
    refetchInterval: 60000, // Check every minute
  });

  useEffect(() => {
    if (!reminders || reminders.length === 0) return;

    // Filter out reminders that have already been shown
    const newReminders = reminders.filter(
      (r) => !activeReminders.find((ar) => ar.id === r.id)
    );

    if (newReminders.length > 0) {
      setActiveReminders((prev) => [...prev, ...newReminders]);

      // Mark reminders as inactive after showing them
      newReminders.forEach(async (reminder) => {
        await supabase
          .from("task_reminders")
          .update({ is_active: false })
          .eq("id", reminder.id);
      });
    }
  }, [reminders]);

  const dismissReminder = (id: string) => {
    setActiveReminders((prev) => prev.filter((r) => r.id !== id));
  };

  return {
    activeReminders,
    dismissReminder,
  };
}

import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '@/hooks/useAuth';
import { supabase } from '@/integrations/supabase/client';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { useToast } from '@/hooks/use-toast';
import { ArrowRight } from 'lucide-react';
import { TaskTemplateSelector } from '@/components/project/TaskTemplateSelector';

const ProjectNew = () => {
  const navigate = useNavigate();
  const { user } = useAuth();
  const { toast } = useToast();
  const [loading, setLoading] = useState(false);

  const [formData, setFormData] = useState({
    client_name: '',
    address: '',
    gush: '',
    parcel: '',
    plot: '',
    priority: '',
  });

  const [taskTemplate, setTaskTemplate] = useState({
    templateType: 'permit',
    customTemplateName: '',
    importedTasks: [] as any[],
  });

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!user) return;

    setLoading(true);

    try {
      // Create project
      const { data: project, error: projectError } = await supabase
        .from('projects')
        .insert([
          {
            client_name: formData.client_name,
            address: formData.address || null,
            gush: formData.gush || null,
            parcel: formData.parcel || null,
            plot: formData.plot || null,
            priority: formData.priority ? parseInt(formData.priority) : null,
            created_by: user.id,
          },
        ])
        .select()
        .single();

      if (projectError) throw projectError;

      // If user imported tasks from a custom list, create a new category and tasks
      if (taskTemplate.templateType === 'custom' && taskTemplate.importedTasks.length > 0) {
        console.log('[ProjectNew] Creating custom category and tasks from imported list...', taskTemplate.importedTasks);

        // Create a new category for this custom template
        const categoryName = taskTemplate.customTemplateName || `קטגוריה מותאמת - ${formData.client_name}`;

        const { data: newCategory, error: categoryError } = await supabase
          .from('categories')
          .insert({
            name: categoryName.toLowerCase().replace(/\s+/g, '_'),
            display_name: categoryName,
            color: '#3B82F6',
            order_index: 999,
          })
          .select('id')
          .single();

        if (categoryError) throw categoryError;

        const tasksToInsert = taskTemplate.importedTasks.map((task, index) => ({
          name: task.name || task.title || `משימה ${index + 1}`,
          description: task.description || task.desc || null,
          category_id: newCategory.id,
          order_index: index + 1,
          is_required: false,
        }));

        const { data: insertedTasks, error: insertTasksError } = await supabase
          .from('tasks')
          .insert(tasksToInsert)
          .select('id');
        if (insertTasksError) throw insertTasksError;

        const projectTasks = insertedTasks.map((t) => ({
          project_id: project.id,
          task_id: t.id,
          completed: false,
        }));

        const { error: linkError } = await supabase.from('project_tasks').insert(projectTasks);
        if (linkError) throw linkError;
        console.log('[ProjectNew] Created category and linked', projectTasks.length, 'tasks to project');
      }

      toast({
        title: 'הפרויקט נוצר בהצלחה',
        description: `פרויקט ${formData.client_name} נוסף למערכת`,
      });
      navigate(`/project/${project.id}`);
    } catch (error: any) {
      toast({
        title: 'שגיאה ביצירת פרויקט',
        description: error.message,
        variant: 'destructive',
      });
    } finally {
      setLoading(false);
    }
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value,
    });
  };

  return (
    <div className="min-h-screen bg-background" dir="rtl">
      <header className="border-b bg-card">
        <div className="container mx-auto px-4 py-4 flex items-center gap-4">
          <Button variant="ghost" size="sm" onClick={() => navigate('/')}>
            <ArrowRight className="ml-2 h-4 w-4" />
            חזור
          </Button>
          <div>
            <h1 className="text-xl font-bold">פרויקט חדש</h1>
          </div>
        </div>
      </header>

      <main className="container mx-auto px-4 py-8 max-w-2xl">
        <Card>
          <CardHeader>
            <CardTitle>פרטי הפרויקט</CardTitle>
            <CardDescription>הזן את הפרטים הבסיסיים של הפרויקט החדש</CardDescription>
          </CardHeader>
          <CardContent>
            <form onSubmit={handleSubmit} className="space-y-4">
              <div className="space-y-2">
                <Label htmlFor="client_name">שם הלקוח *</Label>
                <Input
                  id="client_name"
                  name="client_name"
                  value={formData.client_name}
                  onChange={handleChange}
                  required
                  placeholder="הזן שם לקוח"
                />
              </div>

              <div className="space-y-2">
                <Label htmlFor="address">כתובת</Label>
                <Input
                  id="address"
                  name="address"
                  value={formData.address}
                  onChange={handleChange}
                  placeholder="כתובת הפרויקט"
                />
              </div>

              <div className="grid grid-cols-3 gap-4">
                <div className="space-y-2">
                  <Label htmlFor="gush">גוש</Label>
                  <Input
                    id="gush"
                    name="gush"
                    value={formData.gush}
                    onChange={handleChange}
                    placeholder="מספר גוש"
                  />
                </div>

                <div className="space-y-2">
                  <Label htmlFor="parcel">חלקה</Label>
                  <Input
                    id="parcel"
                    name="parcel"
                    value={formData.parcel}
                    onChange={handleChange}
                    placeholder="מספר חלקה"
                  />
                </div>

                <div className="space-y-2">
                  <Label htmlFor="plot">מגרש</Label>
                  <Input
                    id="plot"
                    name="plot"
                    value={formData.plot}
                    onChange={handleChange}
                    placeholder="מספר מגרש"
                  />
                </div>
              </div>

              <div className="space-y-2">
                <Label htmlFor="priority">עדיפות</Label>
                <Input
                  id="priority"
                  name="priority"
                  type="number"
                  value={formData.priority}
                  onChange={handleChange}
                  placeholder="מספר עדיפות (1-10)"
                  min="1"
                  max="10"
                />
              </div>

              <div className="flex gap-4 pt-4">
                <Button type="submit" disabled={loading} className="flex-1">
                  {loading ? 'יוצר פרויקט...' : 'צור פרויקט'}
                </Button>
                <Button type="button" variant="outline" onClick={() => navigate('/')}>
                  ביטול
                </Button>
              </div>
            </form>
          </CardContent>
        </Card>

        <div className="mt-6">
          <TaskTemplateSelector
            value={taskTemplate}
            onChange={setTaskTemplate}
          />
        </div>
      </main>
    </div>
  );
};

export default ProjectNew;

import { useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useQuery } from '@tanstack/react-query';
import { supabase } from '@/integrations/supabase/client';
import { useAuth } from '@/hooks/useAuth';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { ArrowRight, Building2, MapPin } from 'lucide-react';
import { WorkflowCategories } from '@/components/project/WorkflowCategories';
import { NotificationCenter } from '@/components/project/NotificationCenter';
import { ThemeSelector } from '@/components/project/ThemeSelector';

interface Project {
  id: string;
  client_name: string;
  address: string | null;
  gush: string | null;
  parcel: string | null;
  plot: string | null;
  priority: number | null;
}

const ProjectView = () => {
  const { projectId } = useParams();
  const navigate = useNavigate();
  const { user, loading: authLoading } = useAuth();

  useEffect(() => {
    if (!authLoading && !user) {
      navigate('/auth');
    }
  }, [user, authLoading, navigate]);

  const { data: project, isLoading } = useQuery({
    queryKey: ['project', projectId],
    queryFn: async () => {
      const { data, error } = await supabase
        .from('projects')
        .select('*')
        .eq('id', projectId)
        .single();

      if (error) throw error;
      return data as Project;
    },
    enabled: !!user && !!projectId,
  });

  if (authLoading || isLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-background">
        <div className="flex flex-col items-center gap-4">
          <div className="animate-spin rounded-full h-16 w-16 border-4 border-primary border-t-transparent shadow-glow"></div>
          <p className="text-sm text-muted-foreground animate-pulse">טוען פרויקט...</p>
        </div>
      </div>
    );
  }

  if (!user || !project) {
    return null;
  }

  return (
    <div className="min-h-screen bg-gradient-subtle" dir="rtl">
      <header className="border-b bg-card/80 backdrop-blur-md shadow-md sticky top-0 z-20">
        <div className="container mx-auto px-4 py-4">
          <div className="flex items-center gap-4">
            <Button variant="ghost" size="sm" onClick={() => navigate('/')} className="hover-lift">
              <ArrowRight className="ml-2 h-4 w-4" />
              חזור לפרויקטים
            </Button>
            <div className="flex-1 animate-fade-in">
              <div className="flex items-center gap-2">
                <Building2 className="h-5 w-5 text-primary" />
                <h1 className="text-xl font-bold gradient-text">{project.client_name}</h1>
              </div>
              {project.address && (
                <p className="text-sm text-muted-foreground flex items-center gap-1 mt-1">
                  <MapPin className="h-3 w-3" />
                  {project.address}
                </p>
              )}
            </div>
            <div className="flex items-center gap-2">
              <ThemeSelector />
              <NotificationCenter />
            </div>
          </div>
        </div>
      </header>

      <main className="container mx-auto px-4 py-8 animate-fade-in">
        <div className="space-y-6">
          {(project.gush || project.parcel || project.plot) && (
            <Card>
              <CardHeader>
                <CardTitle className="text-base">פרטי נכס</CardTitle>
              </CardHeader>
              <CardContent>
                <div className="grid grid-cols-3 gap-4 text-sm">
                  {project.gush && (
                    <div>
                      <span className="text-muted-foreground">גוש: </span>
                      <span className="font-medium">{project.gush}</span>
                    </div>
                  )}
                  {project.parcel && (
                    <div>
                      <span className="text-muted-foreground">חלקה: </span>
                      <span className="font-medium">{project.parcel}</span>
                    </div>
                  )}
                  {project.plot && (
                    <div>
                      <span className="text-muted-foreground">מגרש: </span>
                      <span className="font-medium">{project.plot}</span>
                    </div>
                  )}
                </div>
              </CardContent>
            </Card>
          )}

          <WorkflowCategories projectId={project.id} />
        </div>
      </main>
    </div>
  );
};

export default ProjectView;
